import type { GuidedLab } from '../../../quizBank';

export const GUIDED: Record<string, GuidedLab> = {"labex-matplotlib-creating-tickels-from-a-list-of-values":{"intro":"In this tutorial, you will learn how to use Matplotlib to create tick labels from a list of values. When using .Axes.set_xticks, the tick labels are set on the currently chosen ticks. However, sometimes it is better to allow Matplotlib to dynamically choose the number of ticks and their spacing. In this case, you may want to determine the tick label from the value at the tick. This tutorial will show you how to do this.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We begin by importing the necessary libraries for this tutorial, which are matplotlib.pyplot and MaxNLocator from matplotlib.ticker."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nfrom matplotlib.ticker import MaxNLocator"}]},{"title":"Create a figure and axes object","body":["Create a figure and axes object","Next, we create a figure and axes object using the subplots() method from matplotlib.pyplot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Create the x and y data","body":["We create the x and y data using the range() method from Python's built-in range function."],"code":[{"lang":"python","text":"xs = range(26)\nys = range(26)"}]},{"title":"Create a list of labels","body":["We create a list of labels using the list() method to convert a string of the alphabet to a list of characters."],"code":[{"lang":"python","text":"labels = list('abcdefghijklmnopqrstuvwxyz')"}]},{"title":"Create a formatting function","body":["We create a formatting function that determines the tick label from the value at the tick. If the tick value is an integer in the range of xs, the corresponding label from the labels list is returned. Otherwise, an empty string is returned."],"code":[{"lang":"python","text":"def format_fn(tick_val, tick_pos):\n    if int(tick_val) in xs:\n        return labels[int(tick_val)]\n    else:\n        return ''"}]},{"title":"Set the tick formatter and locator","body":["Set the tick formatter and locator","We set the x-axis tick formatter to the formatting function created in Step 5 using the set_major_formatter() method. We also set the x-axis tick locator to MaxNLocator(integer=True) to ensure that the tick values take integer values."],"code":[{"lang":"python","text":"ax.xaxis.set_major_formatter(format_fn)\nax.xaxis.set_major_locator(MaxNLocator(integer=True))"}]},{"title":"Create the plot","body":["We create the plot using the plot() method from the axes object and pass in the xs and ys data."],"code":[{"lang":"python","text":"ax.plot(xs, ys)"}]},{"title":"Display the plot","body":["Finally, we display the plot using the show() method from matplotlib.pyplot."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-tick-locators":{"intro":"In this tutorial, we will learn how to define the position of ticks in a matplotlib plot using tick locators. Tick locators help to make plots more readable by defining the position of the ticks on the x and y-axes. We will cover different types of tick locators and how to implement them in a matplotlib plot.","steps":[{"title":"Importing Libraries","body":["The first step is to import the necessary libraries. We will be using matplotlib.pyplot and matplotlib.ticker."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.ticker as ticker\nimport numpy as np"}]},{"title":"Setting up the Plot","body":["Next, we will set up the plot by creating a figure and an array of subplots. We will also define a setup function that sets up common parameters for the axes in the example."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(8, 1, figsize=(8, 6))\n\ndef setup(ax, title):\n    \"\"\"Set up common parameters for the Axes in the example.\"\"\"\n    # only show the bottom spine\n    ax.yaxis.set_major_locator(ticker.NullLocator())\n    ax.spines[['left', 'right', 'top']].set_visible(False)\n\n    ax.xaxis.set_ticks_position('bottom')\n    ax.tick_params(which='major', width=1.00, length=5)\n    ax.tick_params(which='minor', width=0.75, length=2.5)\n    ax.set_xlim(0, 5)\n    ax.set_ylim(0, 1)\n    ax.text(0.0, 0.2, title, transform=ax.transAxes,\n            fontsize=14, fontname='Monospace', color='tab:blue')"}]},{"title":"Defining the Null Locator","body":["The null locator is a locator that does not place any ticks on the axis. We can define the null locator using ticker.NullLocator()."],"code":[{"lang":"python","text":"setup(axs[0], title=\"NullLocator()\")\naxs[0].xaxis.set_major_locator(ticker.NullLocator())\naxs[0].xaxis.set_minor_locator(ticker.NullLocator())"}]},{"title":"Defining the Multiple Locator","body":["The multiple locator is a locator that places ticks at regular intervals. We can define the multiple locator using ticker.MultipleLocator()."],"code":[{"lang":"python","text":"setup(axs[1], title=\"MultipleLocator(0.5, offset=0.2)\")\naxs[1].xaxis.set_major_locator(ticker.MultipleLocator(0.5, offset=0.2))\naxs[1].xaxis.set_minor_locator(ticker.MultipleLocator(0.1))"}]},{"title":"Defining the Fixed Locator","body":["The fixed locator is a locator that places ticks at fixed locations. We can define the fixed locator using ticker.FixedLocator()."],"code":[{"lang":"python","text":"setup(axs[2], title=\"FixedLocator([0, 1, 5])\")\naxs[2].xaxis.set_major_locator(ticker.FixedLocator([0, 1, 5]))\naxs[2].xaxis.set_minor_locator(ticker.FixedLocator(np.linspace(0.2, 0.8, 4)))"}]},{"title":"Defining the Linear Locator","body":["The linear locator is a locator that places ticks at regular intervals on a linear scale. We can define the linear locator using ticker.LinearLocator()."],"code":[{"lang":"python","text":"setup(axs[3], title=\"LinearLocator(numticks=3)\")\naxs[3].xaxis.set_major_locator(ticker.LinearLocator(3))\naxs[3].xaxis.set_minor_locator(ticker.LinearLocator(31))"}]},{"title":"Defining the Index Locator","body":["The index locator is a locator that places ticks at regular intervals on an index scale. We can define the index locator using ticker.IndexLocator()."],"code":[{"lang":"python","text":"setup(axs[4], title=\"IndexLocator(base=0.5, offset=0.25)\")\naxs[4].plot([0]*5, color='white')\naxs[4].xaxis.set_major_locator(ticker.IndexLocator(base=0.5, offset=0.25))"}]},{"title":"Defining the Auto Locator","body":["The auto locator is a locator that automatically places ticks at regular intervals. We can define the auto locator using ticker.AutoLocator()."],"code":[{"lang":"python","text":"setup(axs[5], title=\"AutoLocator()\")\naxs[5].xaxis.set_major_locator(ticker.AutoLocator())\naxs[5].xaxis.set_minor_locator(ticker.AutoMinorLocator())"}]}],"commands":[],"reference":[{"path":"reference.py","text":"plt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-moving-x-axis-tickels-to-the-top":{"intro":"In this tutorial, we will learn how to move the x-axis tick labels to the top of the plot using Python's Matplotlib library. This can be useful when the x-axis labels are too long and interfere with the plot's readability.","steps":[{"title":"Understanding Matplotlib and Creating a Notebook","body":["Understanding Matplotlib and Creating a Notebook","Matplotlib is a comprehensive library for creating static, animated, and interactive visualizations in Python. It provides an object-oriented API for embedding plots into applications and is widely used for data visualization by scientists, engineers, and data analysts.","In the first cell of your notebook, let's import the Matplotlib library. Type the following code and run the cell by pressing Shift+Enter:","![libraries-imported](../assets/screenshot-20250306-K6iIFfj1@2x.png)"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Check the Matplotlib version\nprint(f\"NumPy version: {np.__version__}\")"},{"lang":"text","text":"NumPy version: 2.0.0"}]},{"title":"Creating a Basic Plot with Default Settings","body":["Creating a Basic Plot with Default Settings","Now that we have Matplotlib imported, let's create a simple plot with default settings to understand how the axes and tick labels are positioned by default.","Understanding Matplotlib Components","In Matplotlib, plots consist of several components:"],"code":[{"lang":"python","text":"# Create a figure and a set of axes\nfig, ax = plt.subplots(figsize=(8, 5))\n\n# Generate some data\nx = np.arange(0, 10, 1)\ny = np.sin(x)\n\n# Plot the data\nax.plot(x, y, marker='o', linestyle='-', color='blue', label='sin(x)')\n\n# Add a title and labels\nax.set_title('A Simple Sine Wave Plot')\nax.set_xlabel('X-axis')\nax.set_ylabel('Y-axis (sin(x))')\n\n# Add a grid and legend\nax.grid(True, linestyle='--', alpha=0.7)\nax.legend()\n\n# Display the plot\nplt.show()\n\nprint(\"Notice that the x-axis tick labels are at the bottom of the plot by default.\")"}]},{"title":"Moving the X-Axis Tick Labels to the Top","body":["Moving the X-Axis Tick Labels to the Top","Now that we understand the default positioning of tick labels, let's move the x-axis tick labels to the top of the plot.","Matplotlib provides the tick_params() method to control the appearance of ticks and tick labels. This method allows us to:","• Show/hide ticks and tick labels • Change their position (top, bottom, left, right) • Adjust their size, color, and other properties"],"code":[{"lang":"python","text":"# Create a new figure and a set of axes\nfig, ax = plt.subplots(figsize=(8, 5))\n\n# Generate some data\nx = np.arange(0, 10, 1)\ny = np.cos(x)\n\n# Plot the data\nax.plot(x, y, marker='s', linestyle='-', color='green', label='cos(x)')\n\n# Move the x-axis tick labels to the top\nax.tick_params(\n    axis='x',         # Apply changes to the x-axis\n    top=True,         # Show ticks on the top side\n    labeltop=True,    # Show tick labels on the top side\n    bottom=False,     # Hide ticks on the bottom side\n    labelbottom=False # Hide tick labels on the bottom side\n)\n\n# Add a title and labels\nax.set_title('Cosine Wave with X-Axis Tick Labels at the Top')\nax.set_xlabel('X-axis (now at the top!)')\nax.set_ylabel('Y-axis (cos(x))')\n\n# Add a grid and legend\nax.grid(True, linestyle='--', alpha=0.7)\nax.legend()\n\n# Display the plot\nplt.show()\n\nprint(\"Now the x-axis tick labels are at the top of the plot!\")"}]},{"title":"Customizing the Plot Further","body":["Now that we have moved the x-axis tick labels to the top, let's further customize our plot to make it more visually appealing and informative.","Advanced Plot Customization Techniques","Matplotlib offers numerous options for customizing plots. Let's explore some of these options:","When you run this code, you will see a much more elaborate and professional-looking plot with:"],"code":[{"lang":"python","text":"# Create a new figure and a set of axes\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate some data with more points for a smoother curve\nx = np.linspace(0, 2*np.pi, 100)\ny1 = np.sin(x)\ny2 = np.cos(x)\n\n# Plot multiple datasets\nax.plot(x, y1, linewidth=2, color='blue', label='sin(x)')\nax.plot(x, y2, linewidth=2, color='red', label='cos(x)')\n\n# Fill the area between curves\nax.fill_between(x, y1, y2, where=(y1 > y2), alpha=0.3, color='green', interpolate=True)\nax.fill_between(x, y1, y2, where=(y1 <= y2), alpha=0.3, color='purple', interpolate=True)\n\n# Move the x-axis tick labels to the top\nax.tick_params(\n    axis='x',\n    top=True,\n    labeltop=True,\n    bottom=False,\n    labelbottom=False\n)\n\n# Customize tick labels\nax.set_xticks(np.arange(0, 2*np.pi + 0.1, np.pi/2))\nax.set_xticklabels(['0', 'π/2', 'π', '3π/2', '2π'])\n\n# Add title and labels with custom styles\nax.set_title('Sine and Cosine Functions with Customized X-Axis Labels at the Top',\n             fontsize=14, fontweight='bold', pad=20)\nax.set_xlabel('Angle (radians)', fontsize=12)\nax.set_ylabel('Function Value', fontsize=12)\n\n# Add a grid and customize its appearance\nax.grid(True, linestyle='--', alpha=0.7, which='both')\n\n# Customize the axis limits\nax.set_ylim(-1.2, 1.2)\n\n# Add a legend with custom location and style\nax.legend(loc='upper right', fontsize=12, framealpha=0.8)\n\n# Add annotations to highlight important points\nax.annotate('Maximum', xy=(np.pi/2, 1), xytext=(np.pi/2, 1.1),\n            arrowprops=dict(facecolor='black', shrink=0.05, width=1.5),\n            fontsize=10, ha='center')"}]},{"title":"Saving and Sharing Your Plot","body":["The final step is to save your customized plot so you can include it in reports, presentations, or share it with others.","Saving Plots in Different Formats","Matplotlib allows you to save plots in various formats including PNG, JPG, PDF, SVG, and more. Let's learn how to save our plot in different formats:","When you run this code, the plot will be saved in three different formats:"],"code":[{"lang":"python","text":"# Create a plot similar to our previous customized one\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate data\nx = np.linspace(0, 2*np.pi, 100)\ny1 = np.sin(x)\ny2 = np.cos(x)\n\n# Plot the data\nax.plot(x, y1, linewidth=2, color='blue', label='sin(x)')\nax.plot(x, y2, linewidth=2, color='red', label='cos(x)')\n\n# Move the x-axis tick labels to the top\nax.tick_params(\n    axis='x',\n    top=True,\n    labeltop=True,\n    bottom=False,\n    labelbottom=False\n)\n\n# Customize tick labels\nax.set_xticks(np.arange(0, 2*np.pi + 0.1, np.pi/2))\nax.set_xticklabels(['0', 'π/2', 'π', '3π/2', '2π'])\n\n# Add title and labels\nax.set_title('Plot with X-Axis Labels at the Top', fontsize=14)\nax.set_xlabel('X-axis at the top')\nax.set_ylabel('Y-axis')\n\n# Add grid and legend\nax.grid(True)\nax.legend()\n\n# Save the figure in different formats\nplt.savefig('plot_with_top_xlabels.png', dpi=300, bbox_inches='tight')\nplt.savefig('plot_with_top_xlabels.pdf', bbox_inches='tight')\nplt.savefig('plot_with_top_xlabels.svg', bbox_inches='tight')\n\n# Show the plot\nplt.show()\n\nprint(\"The plot has been saved in PNG, PDF, and SVG formats in the current directory.\")"},{"lang":"python","text":"# Control the background color and transparency\nfig.patch.set_facecolor('white')  # Set figure background color\nfig.patch.set_alpha(0.8)          # Set background transparency\n\n# Save with custom settings\nplt.savefig('custom_background_plot.png',\n            dpi=400,              # Higher resolution\n            facecolor=fig.get_facecolor(),  # Use the figure's background color\n            edgecolor='none',     # No edge color\n            bbox_inches='tight',  # Tight layout\n            pad_inches=0.1)       # Add a small padding\n\nprint(\"A customized plot has been saved with specialized export settings.\")"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Control the background color and transparency\nfig.patch.set_facecolor('white')  # Set figure background color\nfig.patch.set_alpha(0.8)          # Set background transparency\n\n# Save with custom settings\nplt.savefig('custom_background_plot.png',\n            dpi=400,              # Higher resolution\n            facecolor=fig.get_facecolor(),  # Use the figure's background color\n            edgecolor='none',     # No edge color\n            bbox_inches='tight',  # Tight layout\n            pad_inches=0.1)       # Add a small padding\n\nprint(\"A customized plot has been saved with specialized export settings.\")"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-tickedstroke-in-matplotlib":{"intro":"In Matplotlib, patheffects can be used to alter how paths are drawn. TickedStroke is a type of patheffect that draws lines with a ticked style. This tutorial will guide you through the steps of creating TickedStroke in Matplotlib.","steps":[{"title":"Applying TickedStroke to paths","body":["Applying TickedStroke to paths","In this step, we will apply TickedStroke to paths.","This code will create a unit circle with TickedStroke path effect."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport matplotlib.patches as patches\nimport matplotlib.path as path\nimport matplotlib.patheffects as patheffects\n\nfig, ax = plt.subplots(figsize=(6, 6))\npath = path.Path.unit_circle()\npatch = patches.PathPatch(path, facecolor='none', lw=2, path_effects=[\n    patheffects.withTickedStroke(angle=-90, spacing=10, length=1)])\n\nax.add_patch(patch)\nax.axis('equal')\nax.set_xlim(-2, 2)\nax.set_ylim(-2, 2)\n\nplt.show()"}]},{"title":"Applying TickedStroke to lines","body":["Applying TickedStroke to lines","In this step, we will apply TickedStroke to lines.","This code will create a line and a curve with TickedStroke path effect."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(6, 6))\nax.plot([0, 1], [0, 1], label=\"Line\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=135)])\n\nnx = 101\nx = np.linspace(0.0, 1.0, nx)\ny = 0.3*np.sin(x*8) + 0.4\nax.plot(x, y, label=\"Curve\", path_effects=[patheffects.withTickedStroke()])\n\nax.legend()\n\nplt.show()"}]},{"title":"Applying TickedStroke to contour plots","body":["Applying TickedStroke to contour plots","In this step, we will apply TickedStroke to contour plots.","This code will create a contour plot with TickedStroke path effect."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(6, 6))\n\nnx = 101\nny = 105\n\n# Set up survey vectors\nxvec = np.linspace(0.001, 4.0, nx)\nyvec = np.linspace(0.001, 4.0, ny)\n\n# Set up survey matrices.  Design disk loading and gear ratio.\nx1, x2 = np.meshgrid(xvec, yvec)\n\n# Evaluate some stuff to plot\nobj = x1**2 + x2**2 - 2*x1 - 2*x2 + 2\ng1 = -(3*x1 + x2 - 5.5)\ng2 = -(x1 + 2*x2 - 4.5)\ng3 = 0.8 + x1**-3 - x2\n\ncntr = ax.contour(x1, x2, obj, [0.01, 0.1, 0.5, 1, 2, 4, 8, 16],\n                  colors='black')\nax.clabel(cntr, fmt=\"%2.1f\", use_clabeltext=True)\n\ncg1 = ax.contour(x1, x2, g1, [0], colors='sandybrown')\nplt.setp(cg1.collections,\n         path_effects=[patheffects.withTickedStroke(angle=135)])\n\ncg2 = ax.contour(x1, x2, g2, [0], colors='orangered')\nplt.setp(cg2.collections,\n         path_effects=[patheffects.withTickedStroke(angle=60, length=2)])\n\ncg3 = ax.contour(x1, x2, g3, [0], colors='mediumblue')\nplt.setp(cg3.collections,\n         path_effects=[patheffects.withTickedStroke(spacing=7)])\n\nax.set_xlim(0, 4)\nax.set_ylim(0, 4)\n\nplt.show()"}]},{"title":"Direction/side of the ticks","body":["In this step, we will change the side of the ticks.","This code will create a line with ticks on both sides."],"code":[{"lang":"python","text":"fig, ax = plt.subplots(figsize=(6, 6))\nline_x = line_y = [0, 1]\nax.plot(line_x, line_y, label=\"Line\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=135)])\n\nax.plot(line_x, line_y, label=\"Opposite side\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=-135)])\n\nax.legend()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots(figsize=(6, 6))\nline_x = line_y = [0, 1]\nax.plot(line_x, line_y, label=\"Line\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=135)])\n\nax.plot(line_x, line_y, label=\"Opposite side\",\n        path_effects=[patheffects.withTickedStroke(spacing=7, angle=-135)])\n\nax.legend()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-custom-tickels":{"intro":"Matplotlib is a popular Python library used for data visualization. One of the key features of Matplotlib is the ability to customize the tick labels on a plot. In this lab, you will learn how to rotate custom tick labels using Matplotlib.","steps":[{"title":"Import Matplotlib Library","body":["The first step is to import the Matplotlib library. You can do this by running the following code:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Create Data for Plotting","body":["The second step is to create the data that you want to plot. For this lab, we will use the following data:"],"code":[{"lang":"python","text":"x = [1, 2, 3, 4]\ny = [1, 4, 9, 6]\nlabels = ['Frogs', 'Hogs', 'Bogs', 'Slogs']"}]},{"title":"Plot the Data","body":["The third step is to plot the data using Matplotlib. You can do this by running the following code:"],"code":[{"lang":"python","text":"plt.plot(x, y)"}]},{"title":"Customize the Tick Labels","body":["The fourth step is to customize the tick labels. In this lab, we will rotate the tick labels vertically. You can do this by running the following code:"],"code":[{"lang":"python","text":"plt.xticks(x, labels, rotation='vertical')"}]},{"title":"Adjust Margins and Spacing","body":["The fifth step is to adjust the margins and spacing of the plot to ensure that the tick labels are not clipped. You can do this by running the following code:"],"code":[{"lang":"python","text":"plt.margins(0.2)\nplt.subplots_adjust(bottom=0.15)"}]},{"title":"Show the Plot","body":["The final step is to show the plot using Matplotlib. You can do this by running the following code:"],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-fixing-too-many-ticks-in-matplotlib":{"intro":"When working with Matplotlib, it is common to encounter unexpected tick behavior, such as too many ticks or ticks that are out of order. This is often caused by passing a list of strings instead of numbers or datetime objects, which Matplotlib treats as categorical variables by default. This lab will provide step-by-step instructions on how to fix too many ticks in Matplotlib.","steps":[{"title":"Check the Data Type","body":["The first step is to check the data type of the x-axis values. If it is a list of strings, it is likely that the tick behavior is unexpected. To fix this, we need to convert the strings to numeric types. Here is an example:","In this example, we have a list of strings on the x-axis. When we plot the data, the tick labels are out of order and misplaced."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data\nx = ['1', '5', '2', '3']\ny = [1, 4, 2, 3]\n\n# plot the data with string tick labels\nfig, ax = plt.subplots()\nax.plot(x, y, 'd')\nax.set_xlabel('Categories')\nplt.show()"}]},{"title":"Convert Strings to Numeric Types","body":["Convert Strings to Numeric Types","To fix the tick behavior, we need to convert the strings to numeric types. Here is an example:","In this example, we convert the string values to floats using np.asarray(). When we plot the data again, the tick labels are as expected."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data\nx = ['1', '5', '2', '3']\ny = [1, 4, 2, 3]\n\n# convert strings to floats\nx = np.asarray(x, dtype='float')\n\n# plot the data with numeric tick labels\nfig, ax = plt.subplots()\nax.plot(x, y, 'd')\nax.set_xlabel('Floats')\nplt.show()"}]},{"title":"Handle Too Many Ticks","body":["If the x-axis has many elements, all of which are strings, we may end up with too many ticks that are unreadable. In this case, we need to convert the strings to numeric types. Here is an example:","In this example, we have 100 string values on the x-axis, resulting in too many ticks that are unreadable.","To fix this, we need to convert the strings to floats. Here is an example:","In this example, we convert the string values to floats using np.asarray(). When we plot the data again, the tick labels are as expected."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data with 100 elements\nx = [f'{xx}' for xx in np.arange(100)]\ny = np.arange(100)\n\n# plot the data with string tick labels\nfig, ax = plt.subplots()\nax.plot(x, y)\nax.set_xlabel('Categories')\nplt.show()"},{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data with 100 elements\nx = [f'{xx}' for xx in np.arange(100)]\ny = np.arange(100)\n\n# convert strings to floats\nx = np.asarray(x, float)\n\n# plot the data with numeric tick labels\nfig, ax = plt.subplots()\nax.plot(x, y)\nax.set_xlabel('Floats')\nplt.show()"}]},{"title":"Handle DateTime Ticks","body":["When working with datetime values on the x-axis, it is important to convert the strings to datetime objects to get the proper date locators and formatters. Here is an example:","In this example, we convert the string values to datetime64 using np.asarray(). When we plot the data again, the tick labels are as expected."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data with datetime strings\nx = ['2021-10-01', '2021-11-02', '2021-12-03', '2021-09-01']\ny = [0, 2, 3, 1]\n\n# convert strings to datetime64\nx = np.asarray(x, dtype='datetime64[s]')\n\n# plot the data with datetime tick labels\nfig, ax = plt.subplots()\nax.plot(x, y, 'd')\nax.tick_params(axis='x', labelrotation=90)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# create example data with datetime strings\nx = ['2021-10-01', '2021-11-02', '2021-12-03', '2021-09-01']\ny = [0, 2, 3, 1]\n\n# convert strings to datetime64\nx = np.asarray(x, dtype='datetime64[s]')\n\n# plot the data with datetime tick labels\nfig, ax = plt.subplots()\nax.plot(x, y, 'd')\nax.tick_params(axis='x', labelrotation=90)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-time-series-histogram":{"intro":"This lab demonstrates how to efficiently visualize large numbers of time series in a way that could potentially reveal hidden substructure and patterns that are not immediately obvious and display them in a visually appealing way.","steps":[{"title":"Import Required Libraries","body":["In this step, we will import the required libraries for this lab."],"code":[{"lang":"python","text":"import time\nimport matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Generate Data","body":["In this step, we will generate multiple sinusoidal \"signal\" series that are buried under a larger number of random walk \"noise/background\" series. We will generate unbiased Gaussian random walks and sinusoidal signals."],"code":[{"lang":"python","text":"# Fix random state for reproducibility\nnp.random.seed(19680801)\n\n# Make some data; a 1D random walk + small fraction of sine waves\nnum_series = 1000\nnum_points = 100\nSNR = 0.10  # Signal to Noise Ratio\nx = np.linspace(0, 4 * np.pi, num_points)\n\n# Generate unbiased Gaussian random walks\nY = np.cumsum(np.random.randn(num_series, num_points), axis=-1)\n\n# Generate sinusoidal signals\nnum_signal = round(SNR * num_series)\nphi = (np.pi / 8) * np.random.randn(num_signal, 1)  # small random offset\nY[-num_signal:] = (\n    np.sqrt(np.arange(num_points))  # random walk RMS scaling factor\n    * (np.sin(x - phi)\n       + 0.05 * np.random.randn(num_signal, num_points))  # small random noise\n)"}]},{"title":"Visualize Data with Line Plot","body":["In this step, we will visualize the generated data with a line plot."],"code":[{"lang":"python","text":"# Plot series using `plot` and a small value of `alpha`.\n# With this view, it is very difficult to observe the sinusoidal behavior because of how many overlapping series there are.\n# It also takes a bit of time to run because so many individual artists need to be generated.\ntic = time.time()\nplt.plot(x, Y.T, color=\"C0\", alpha=0.1)\ntoc = time.time()\nplt.title(\"Line plot with alpha\")\nplt.show()\nprint(f\"{toc-tic:.3f} sec. elapsed\")"}]},{"title":"Visualize Data with 2D Histogram - Log Color Scale","body":["Visualize Data with 2D Histogram - Log Color Scale","In this step, we will convert the multiple time series into a histogram. Not only will the hidden signal be more visible, but it is also a much quicker procedure. We will plot (x, y) points in 2D histogram with a log color scale."],"code":[{"lang":"python","text":"tic = time.time()\n\n# Linearly interpolate between the points in each time series\nnum_fine = 800\nx_fine = np.linspace(x.min(), x.max(), num_fine)\ny_fine = np.concatenate([np.interp(x_fine, x, y_row) for y_row in Y])\nx_fine = np.broadcast_to(x_fine, (num_series, num_fine)).ravel()\n\n# Plot (x, y) points in 2d histogram with log colorscale\n# It is pretty evident that there is some kind of structure under the noise\n# You can tune vmax to make signal more visible\ncmap = plt.colormaps[\"plasma\"]\ncmap = cmap.with_extremes(bad=cmap(0))\nh, xedges, yedges = np.histogram2d(x_fine, y_fine, bins=[400, 100])\npcm = plt.pcolormesh(xedges, yedges, h.T, cmap=cmap,\n                         norm=\"log\", vmax=1.5e2, rasterized=True)\nplt.colorbar(pcm, label=\"# points\", pad=0)\nplt.title(\"2D Histogram and Log Color Scale\")\nplt.show()\n\ntoc = time.time()\nprint(f\"{toc-tic:.3f} sec. elapsed\")"}]},{"title":"Visualize Data with 2D Histogram - Linear Color Scale","body":["Visualize Data with 2D Histogram - Linear Color Scale","In this step, we will visualize data with a linear color scale."],"code":[{"lang":"python","text":"# Same data but on linear color scale\npcm = plt.pcolormesh(xedges, yedges, h.T, cmap=cmap,\n                         vmax=1.5e2, rasterized=True)\nplt.colorbar(pcm, label=\"# points\", pad=0)\nplt.title(\"2D Histogram and Linear Color Scale\")\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Same data but on linear color scale\npcm = plt.pcolormesh(xedges, yedges, h.T, cmap=cmap,\n                         vmax=1.5e2, rasterized=True)\nplt.colorbar(pcm, label=\"# points\", pad=0)\nplt.title(\"2D Histogram and Linear Color Scale\")\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-matplotlib-timeline-visualizations":{"intro":"In this lab, you will learn how to create a simple timeline using Matplotlib release dates. A timeline is a graphical representation of a sequence of events in chronological order. Timelines can be created with a collection of dates and text. In this example, we will show how to create a simple timeline using the dates for recent releases of Matplotlib.","steps":[{"title":"Fetching Data","body":["To create a timeline, we need to fetch data such as dates and names. In this example, we will use the Matplotlib releases and their dates from GitHub. If the data cannot be fetched due to any reason, we will use fallback data as a backup. Here is the code for fetching data:"],"code":[{"lang":"python","text":"from datetime import datetime\n\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib.dates as mdates\n\ntry:\n    # Try to fetch a list of Matplotlib releases and their dates\n    # from https://api.github.com/repos/matplotlib/matplotlib/releases\n    import json\n    import urllib.request\n\n    url = 'https://api.github.com/repos/matplotlib/matplotlib/releases'\n    url += '?per_page=100'\n    data = json.loads(urllib.request.urlopen(url, timeout=1).read().decode())\n\n    dates = []\n    names = []\n    for item in data:\n        if 'rc' not in item['tag_name'] and 'b' not in item['tag_name']:\n            dates.append(item['published_at'].split(\"T\")[0])\n            names.append(item['tag_name'])\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]\n\nexcept Exception:\n    # In case the above fails, e.g. because of missing internet connection\n    # use the following lists as fallback.\n    names = ['v2.2.4', 'v3.0.3', 'v3.0.2', 'v3.0.1', 'v3.0.0', 'v2.2.3',\n             'v2.2.2', 'v2.2.1', 'v2.2.0', 'v2.1.2', 'v2.1.1', 'v2.1.0',\n             'v2.0.2', 'v2.0.1', 'v2.0.0', 'v1.5.3', 'v1.5.2', 'v1.5.1',\n             'v1.5.0', 'v1.4.3', 'v1.4.2', 'v1.4.1', 'v1.4.0']\n\n    dates = ['2019-02-26', '2019-02-26', '2018-11-10', '2018-11-10',\n             '2018-09-18', '2018-08-10', '2018-03-17', '2018-03-16',\n             '2018-03-06', '2018-01-18', '2017-12-10', '2017-10-07',\n             '2017-05-10', '2017-05-02', '2017-01-17', '2016-09-09',\n             '2016-07-03', '2016-01-10', '2015-10-29', '2015-02-16',\n             '2014-10-26', '2014-10-18', '2014-08-26']\n\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]"}]},{"title":"Creating a Stem Plot","body":["Next, we will create a stem plot with some variation in levels as to distinguish even close-by events. We add markers on the baseline for visual emphasis on the one-dimensional nature of the timeline. For each event, we add a text label via ~.Axes.annotate, which is offset in units of points from the tip of the event line. Here is the code for creating a stem plot:"],"code":[{"lang":"python","text":"# Choose some nice levels\nlevels = np.tile([-5, 5, -3, 3, -1, 1],\n                 int(np.ceil(len(dates)/6)))[:len(dates)]\n\n# Create figure and plot a stem plot with the date\nfig, ax = plt.subplots(figsize=(8.8, 4), layout=\"constrained\")\nax.set(title=\"Matplotlib release dates\")\n\nax.vlines(dates, 0, levels, color=\"tab:red\")  # The vertical stems.\nax.plot(dates, np.zeros_like(dates), \"-o\",\n        color=\"k\", markerfacecolor=\"w\")  # Baseline and markers on it.\n\n# annotate lines\nfor d, l, r in zip(dates, levels, names):\n    ax.annotate(r, xy=(d, l),\n                xytext=(-3, np.sign(l)*3), textcoords=\"offset points\",\n                horizontalalignment=\"right\",\n                verticalalignment=\"bottom\" if l > 0 else \"top\")"}]},{"title":"Formatting the Plot","body":["Now, we will format the plot by adding x-axis and y-axis labels, setting x-axis major locator and formatter, and removing y-axis and spines. Here is the code for formatting the plot:"],"code":[{"lang":"python","text":"# format x-axis with 4-month intervals\nax.xaxis.set_major_locator(mdates.MonthLocator(interval=4))\nax.xaxis.set_major_formatter(mdates.DateFormatter(\"%b %Y\"))\nplt.setp(ax.get_xticklabels(), rotation=30, ha=\"right\")\n\n# remove y-axis and spines\nax.yaxis.set_visible(False)\nax.spines[[\"left\", \"top\", \"right\"]].set_visible(False)\n\nax.margins(y=0.1)\nplt.show()"}]},{"title":"Putting it all Together","body":["Here is the final code for creating a simple timeline using Matplotlib release dates:"],"code":[{"lang":"python","text":"from datetime import datetime\n\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib.dates as mdates\n\ntry:\n    # Try to fetch a list of Matplotlib releases and their dates\n    # from https://api.github.com/repos/matplotlib/matplotlib/releases\n    import json\n    import urllib.request\n\n    url = 'https://api.github.com/repos/matplotlib/matplotlib/releases'\n    url += '?per_page=100'\n    data = json.loads(urllib.request.urlopen(url, timeout=1).read().decode())\n\n    dates = []\n    names = []\n    for item in data:\n        if 'rc' not in item['tag_name'] and 'b' not in item['tag_name']:\n            dates.append(item['published_at'].split(\"T\")[0])\n            names.append(item['tag_name'])\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]\n\nexcept Exception:\n    # In case the above fails, e.g. because of missing internet connection\n    # use the following lists as fallback.\n    names = ['v2.2.4', 'v3.0.3', 'v3.0.2', 'v3.0.1', 'v3.0.0', 'v2.2.3',\n             'v2.2.2', 'v2.2.1', 'v2.2.0', 'v2.1.2', 'v2.1.1', 'v2.1.0',\n             'v2.0.2', 'v2.0.1', 'v2.0.0', 'v1.5.3', 'v1.5.2', 'v1.5.1',\n             'v1.5.0', 'v1.4.3', 'v1.4.2', 'v1.4.1', 'v1.4.0']\n\n    dates = ['2019-02-26', '2019-02-26', '2018-11-10', '2018-11-10',\n             '2018-09-18', '2018-08-10', '2018-03-17', '2018-03-16',\n             '2018-03-06', '2018-01-18', '2017-12-10', '2017-10-07',\n             '2017-05-10', '2017-05-02', '2017-01-17', '2016-09-09',\n             '2016-07-03', '2016-01-10', '2015-10-29', '2015-02-16',\n             '2014-10-26', '2014-10-18', '2014-08-26']\n\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]\n\n# Choose some nice levels\nlevels = np.tile([-5, 5, -3, 3, -1, 1],\n                 int(np.ceil(len(dates)/6)))[:len(dates)]"}]}],"commands":[],"reference":[{"path":"reference.py","text":"from datetime import datetime\n\nimport matplotlib.pyplot as plt\nimport numpy as np\n\nimport matplotlib.dates as mdates\n\ntry:\n    # Try to fetch a list of Matplotlib releases and their dates\n    # from https://api.github.com/repos/matplotlib/matplotlib/releases\n    import json\n    import urllib.request\n\n    url = 'https://api.github.com/repos/matplotlib/matplotlib/releases'\n    url += '?per_page=100'\n    data = json.loads(urllib.request.urlopen(url, timeout=1).read().decode())\n\n    dates = []\n    names = []\n    for item in data:\n        if 'rc' not in item['tag_name'] and 'b' not in item['tag_name']:\n            dates.append(item['published_at'].split(\"T\")[0])\n            names.append(item['tag_name'])\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]\n\nexcept Exception:\n    # In case the above fails, e.g. because of missing internet connection\n    # use the following lists as fallback.\n    names = ['v2.2.4', 'v3.0.3', 'v3.0.2', 'v3.0.1', 'v3.0.0', 'v2.2.3',\n             'v2.2.2', 'v2.2.1', 'v2.2.0', 'v2.1.2', 'v2.1.1', 'v2.1.0',\n             'v2.0.2', 'v2.0.1', 'v2.0.0', 'v1.5.3', 'v1.5.2', 'v1.5.1',\n             'v1.5.0', 'v1.4.3', 'v1.4.2', 'v1.4.1', 'v1.4.0']\n\n    dates = ['2019-02-26', '2019-02-26', '2018-11-10', '2018-11-10',\n             '2018-09-18', '2018-08-10', '2018-03-17', '2018-03-16',\n             '2018-03-06', '2018-01-18', '2017-12-10', '2017-10-07',\n             '2017-05-10', '2017-05-02', '2017-01-17', '2016-09-09',\n             '2016-07-03', '2016-01-10', '2015-10-29', '2015-02-16',\n             '2014-10-26', '2014-10-18', '2014-08-26']\n\n    # Convert date strings (e.g. 2014-10-18) to datetime\n    dates = [datetime.strptime(d, \"%Y-%m-%d\") for d in dates]\n\n# Choose some nice levels\nlevels = np.tile([-5, 5, -3, 3, -1, 1],\n                 int(np.ceil(len(dates)/6)))[:len(dates)]"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-using-matplotlib-general-timer-objects":{"intro":"This lab aims to explain how to use general timer objects in Matplotlib. This is a simple example that is used to update the time placed in the title of the figure.","steps":[{"title":"Import Required Libraries","body":["Import the required libraries for the code to function properly."],"code":[{"lang":"python","text":"from datetime import datetime\nimport matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Function to Update Title","body":["Define Function to Update Title","Define the function to update the title of the figure with the current time."],"code":[{"lang":"python","text":"def update_title(axes):\n    axes.set_title(datetime.now())\n    axes.figure.canvas.draw()"}]},{"title":"Create Figure and Axes","body":["Create a figure and axes for the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()"}]},{"title":"Plot Data","body":["Create data to plot and plot it on the axes."],"code":[{"lang":"python","text":"x = np.linspace(-3, 3)\nax.plot(x, x ** 2)"}]},{"title":"Create Timer Object","body":["Create a new timer object. Set the interval to 100 milliseconds (1000 is default) and tell the timer what function should be called."],"code":[{"lang":"python","text":"timer = fig.canvas.new_timer(interval=100)\ntimer.add_callback(update_title, ax)"}]},{"title":"Start Timer","body":[],"code":[{"lang":"python","text":"timer.start()"}]},{"title":"Show Plot","body":[],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-plot-title-positioning":{"intro":"In this lab, you will learn how to position the titles of plots in Matplotlib. Matplotlib can display plot titles centered, flush with the left side of a set of axes, and flush with the right side of a set of axes. This lab will show you how to use Matplotlib to position plot titles in different ways.","steps":[{"title":"Basic Plotting with Default Title Position","body":["Basic Plotting with Default Title Position","In this step, you will create a simple line plot and add a centered title, which is the default position in Matplotlib.","If you encounter any issues during the lab, feel free to ask Labby for assistance. Please provide feedback after the session so we can promptly address any problems.","Now, let's start by importing the Matplotlib library. In the first cell of your notebook, type the following code and run it by pressing Shift+Enter:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"},{"lang":"python","text":"plt.figure(figsize=(8, 5))  # Create a figure with a specific size\nplt.plot(range(10))         # Plot numbers from 0 to 9\nplt.grid(True)              # Add a grid for better readability\nplt.show()                  # Display the plot"},{"lang":"python","text":"plt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('My First Matplotlib Plot')  # Add a centered title\nplt.show()"}]},{"title":"Left and Right Title Positioning","body":["Left and Right Title Positioning","Matplotlib allows you to position the title to the left or right side of the plot using the loc parameter. In this step, you will learn how to align titles to the left and right sides of your plots.","Creating a Plot with a Left-Aligned Title","Let's create a plot with the title positioned at the left side. In a new cell, enter the following code:"],"code":[{"lang":"python","text":"plt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('Left-Aligned Title', loc='left')  # Position the title at the left\nplt.show()"},{"lang":"python","text":"plt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('Right-Aligned Title', loc='right')  # Position the title at the right\nplt.show()"},{"lang":"python","text":"# Create a figure with 3 subplots arranged horizontally\nfig, axes = plt.subplots(1, 3, figsize=(15, 4))\n\n# Plot 1: Center-aligned title (default)\naxes[0].plot(range(10))\naxes[0].grid(True)\naxes[0].set_title('Center Title')\n\n# Plot 2: Left-aligned title\naxes[1].plot(range(10))\naxes[1].grid(True)\naxes[1].set_title('Left Title', loc='left')\n\n# Plot 3: Right-aligned title\naxes[2].plot(range(10))\naxes[2].grid(True)\naxes[2].set_title('Right Title', loc='right')\n\nplt.tight_layout()  # Adjust spacing between subplots\nplt.show()"}]},{"title":"Custom Title Vertical Positioning","body":["Custom Title Vertical Positioning","Sometimes you might want to adjust the vertical position of your title. In this step, you'll learn how to manually control the vertical (y-axis) position of your plot titles.","Understanding Y-Position in Titles","The vertical position of a title can be adjusted using the y parameter in the title() function. The y parameter accepts values in normalized coordinates, where:"],"code":[{"lang":"python","text":"plt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('Higher Title Position', y=1.1)  # Position the title higher\nplt.show()"},{"lang":"python","text":"plt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('Lower Title Position', y=0.9)  # Position the title lower\nplt.show()"},{"lang":"python","text":"# Create a figure with 3 subplots arranged horizontally\nfig, axes = plt.subplots(1, 3, figsize=(15, 4))\n\n# Plot 1: Default Y-position\naxes[0].plot(range(10))\naxes[0].grid(True)\naxes[0].set_title('Default Position (y=1.0)')\n\n# Plot 2: Higher Y-position\naxes[1].plot(range(10))\naxes[1].grid(True)\naxes[1].set_title('Higher Position', y=1.15)\n\n# Plot 3: Lower Y-position\naxes[2].plot(range(10))\naxes[2].grid(True)\naxes[2].set_title('Lower Position', y=0.85)\n\nplt.tight_layout()  # Adjust spacing between subplots\nplt.show()"}]},{"title":"Advanced Title Positioning with Subplots","body":["Advanced Title Positioning with Subplots","In this step, you'll learn advanced techniques for title positioning when working with subplot layouts and axes objects. You'll also learn how to use the suptitle() function to add an overall title to a figure with multiple subplots.","Creating a Figure with Subplots and Individual Titles","Let's create a 2x2 grid of subplots, each with its own title positioned differently:"],"code":[{"lang":"python","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\n\n# Flatten the 2D array of axes for easier iteration\naxes = axes.flatten()\n\n# Plot data and set titles with different positions for each subplot\nfor i, ax in enumerate(axes):\n    ax.plot(range(10))\n    ax.grid(True)\n\n# Top-left subplot: Default centered title\naxes[0].set_title('Default (Centered)')\n\n# Top-right subplot: Left-aligned title\naxes[1].set_title('Left-Aligned', loc='left')\n\n# Bottom-left subplot: Right-aligned title\naxes[2].set_title('Right-Aligned', loc='right')\n\n# Bottom-right subplot: Custom positioned title\naxes[3].set_title('Custom Position', y=0.85, loc='center')\n\n# Add spacing between subplots\nplt.tight_layout()\nplt.show()"},{"lang":"python","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\n\n# Flatten the 2D array of axes for easier iteration\naxes = axes.flatten()\n\n# Plot data on each subplot\nfor i, ax in enumerate(axes):\n    ax.plot(range(10))\n    ax.grid(True)\n    ax.set_title(f'Subplot {i+1}')\n\n# Add an overall title to the figure\nfig.suptitle('Multiple Subplots with an Overall Title', fontsize=16)\n\n# Add spacing between subplots\nplt.tight_layout()\n# Add top spacing for the suptitle\nplt.subplots_adjust(top=0.9)\nplt.show()"},{"lang":"python","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\n\n# Plot data on each subplot with different title positions\naxes[0, 0].plot(range(10))\naxes[0, 0].grid(True)\naxes[0, 0].set_title('Centered Title', loc='center')\n\naxes[0, 1].plot(range(10))\naxes[0, 1].grid(True)\naxes[0, 1].set_title('Left-Aligned Title', loc='left')\n\naxes[1, 0].plot(range(10))\naxes[1, 0].grid(True)\naxes[1, 0].set_title('Right-Aligned Title', loc='right')\n\naxes[1, 1].plot(range(10))\naxes[1, 1].grid(True)\naxes[1, 1].set_title('Lower Title', y=0.85)\n\n# Add an overall title to the figure\nfig.suptitle('Advanced Title Positioning Demo', fontsize=16)\n\n# Add spacing between subplots\nplt.tight_layout()\n# Add top spacing for the suptitle\nplt.subplots_adjust(top=0.9)\nplt.show()"}]},{"title":"Global Title Positioning with RCParams","body":["Global Title Positioning with RCParams","In this final step, you'll learn how to use Matplotlib's runtime configuration parameters (RCParams) to set global defaults for title positioning. This is useful when you want all plots in your notebook or script to use consistent title positioning without having to specify it for each plot individually.","Understanding RCParams in Matplotlib","Matplotlib's behavior can be customized using a dictionary-like variable called rcParams. This allows you to set global defaults for various properties, including title positioning."],"code":[{"lang":"python","text":"# View the current default values\nprint(\"Default title y position:\", plt.rcParams['axes.titley'])\nprint(\"Default title padding:\", plt.rcParams['axes.titlepad'])"},{"lang":"python","text":"# Set new global defaults for title positioning\nplt.rcParams['axes.titley'] = 1.05     # Set title y position higher\nplt.rcParams['axes.titlepad'] = 10     # Set padding between title and plot\nplt.rcParams['axes.titlelocation'] = 'left'  # Set default alignment to left\n\n# Create a plot that will use the new defaults\nplt.figure(figsize=(8, 5))\nplt.plot(range(10))\nplt.grid(True)\nplt.title('This Title Uses Global RCParams Settings')\nplt.show()"},{"lang":"python","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\n\n# Flatten the 2D array of axes for easier iteration\naxes = axes.flatten()\n\n# Plot data on each subplot with titles that use global settings\nfor i, ax in enumerate(axes):\n    ax.plot(range(10))\n    ax.grid(True)\n    ax.set_title(f'Subplot {i+1} Using Global Settings')\n\nplt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create a figure with a 2x2 grid of subplots\nfig, axes = plt.subplots(2, 2, figsize=(10, 8))\n\n# Flatten the 2D array of axes for easier iteration\naxes = axes.flatten()\n\n# Plot data on each subplot with titles that use global settings\nfor i, ax in enumerate(axes):\n    ax.plot(range(10))\n    ax.grid(True)\n    ax.set_title(f'Subplot {i+1} Using Global Settings')\n\nplt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-tool-manager":{"intro":"This tutorial will show you how to modify the Toolbar, create tools, add tools, and remove tools using matplotlib.backend_managers.ToolManager.","steps":[{"title":"List all the tools controlled by the ToolManager","body":["List all the tools controlled by the ToolManager","The first step is to list all the tools controlled by the ToolManager. This can be achieved by creating a custom tool named ListTools. The ListTools class inherits from ToolBase. The trigger() method of ListTools prints the name, description and keymap of all the available tools."],"code":[{"lang":"python","text":"class ListTools(ToolBase):\n    \"\"\"List all the tools controlled by the `ToolManager`.\"\"\"\n    default_keymap = 'm'  # keyboard shortcut\n    description = 'List Tools'\n\n    def trigger(self, *args, **kwargs):\n        print('_' * 80)\n        fmt_tool = \"{:12} {:45} {}\".format\n        print(fmt_tool('Name (id)', 'Tool description', 'Keymap'))\n        print('-' * 80)\n        tools = self.toolmanager.tools\n        for name in sorted(tools):\n            if not tools[name].description:\n                continue\n            keys = ', '.join(sorted(self.toolmanager.get_tool_keymap(name)))\n            print(fmt_tool(name, tools[name].description, keys))\n        print('_' * 80)\n        fmt_active_toggle = \"{!s:12} {!s:45}\".format\n        print(\"Active Toggle tools\")\n        print(fmt_active_toggle(\"Group\", \"Active\"))\n        print('-' * 80)\n        for group, active in self.toolmanager.active_toggle.items():\n            print(fmt_active_toggle(group, active))"}]},{"title":"Show lines with a given gid","body":["The second step is to create a custom tool named GroupHideTool. The GroupHideTool class inherits from ToolToggleBase. The set_lines_visibility() method of GroupHideTool sets the visibility of all the lines on the plot which have the specified gid to either True or False, depending on whether the tool is enabled or disabled."],"code":[{"lang":"python","text":"class GroupHideTool(ToolToggleBase):\n    \"\"\"Show lines with a given gid.\"\"\"\n    default_keymap = 'S'\n    description = 'Show by gid'\n    default_toggled = True\n\n    def __init__(self, *args, gid, **kwargs):\n        self.gid = gid\n        super().__init__(*args, **kwargs)\n\n    def enable(self, *args):\n        self.set_lines_visibility(True)\n\n    def disable(self, *args):\n        self.set_lines_visibility(False)\n\n    def set_lines_visibility(self, state):\n        for ax in self.figure.get_axes():\n            for line in ax.get_lines():\n                if line.get_gid() == self.gid:\n                    line.set_visible(state)\n        self.figure.canvas.draw()"}]},{"title":"Add custom tools","body":["The third step is to add the custom tools that we created in steps 1 and 2. This can be achieved by calling the add_tool() method of the ToolManager. We add the ListTools and GroupHideTool tools to the ToolManager. We also add the Show tool to the Toolbar, which was created using the add_tool() method of Toolbar."],"code":[{"lang":"python","text":"fig.canvas.manager.toolmanager.add_tool('List', ListTools)\nfig.canvas.manager.toolmanager.add_tool('Show', GroupHideTool, gid='mygroup')\nfig.canvas.manager.toolbar.add_tool('Show', 'navigation', 1)"}]},{"title":"Remove tools","body":["The fourth step is to remove the forward button from the Toolbar. We can achieve this by calling the remove_tool() method of the ToolManager."],"code":[{"lang":"python","text":"fig.canvas.manager.toolmanager.remove_tool('forward')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig.canvas.manager.toolmanager.remove_tool('forward')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-topographic-hillshading-with-matplotlib":{"intro":"This lab demonstrates how to use Matplotlib to create topographic hillshading plots using varying blend modes and vertical exaggeration. The purpose of hillshading is for visual purposes to create a 3D-like effect on 2D maps. In this lab, we will learn how to change the blend modes and vertical exaggeration to achieve different visual effects.","steps":[{"title":"Import Required Libraries","body":["We begin by importing the required libraries, including Matplotlib, NumPy, and LightSource."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.cbook import get_sample_data\nfrom matplotlib.colors import LightSource"}]},{"title":"Load the Data","body":["Next, we load the sample elevation data using the get_sample_data function from Matplotlib. We then extract the elevation data and the cell size of the grid."],"code":[{"lang":"python","text":"dem = get_sample_data('jacksboro_fault_dem.npz')\nz = dem['elevation']\ndx, dy = dem['dx'], dem['dy']"}]},{"title":"Specify the Cell Size","body":["If you need topographically accurate vertical exaggeration, or you don't want to guess at what vert_exag should be, you'll need to specify the cell size of the grid (i.e. the dx and dy parameters). Otherwise, any vert_exag value you specify will be relative to the grid spacing of your input data. In this step, we calculate the dx and dy values in meters."],"code":[{"lang":"python","text":"dy = 111200 * dy\ndx = 111200 * dx * np.cos(np.radians(dem['ymin']))"}]},{"title":"Specify Light Source and Colormap","body":["Specify Light Source and Colormap","We specify the LightSource object by setting the azimuth and altitude of the light source. We also set the colormap to be used in the plot."],"code":[{"lang":"python","text":"ls = LightSource(azdeg=315, altdeg=45)\ncmap = plt.cm.gist_earth"}]},{"title":"Create the Plot","body":["We create a 4x3 plot grid to show the hillshaded plots with different blend modes and vertical exaggeration. We first show the hillshade intensity image in the first row, and then place hillshaded plots with different blend modes in the rest of the rows. We use a for loop to iterate through the different vertical exaggeration values and blend modes."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=4, ncols=3, figsize=(8, 9))\nplt.setp(axs.flat, xticks=[], yticks=[])\n\nfor col, ve in zip(axs.T, [0.1, 1, 10]):\n    col[0].imshow(ls.hillshade(z, vert_exag=ve, dx=dx, dy=dy), cmap='gray')\n    for ax, mode in zip(col[1:], ['hsv', 'overlay', 'soft']):\n        rgb = ls.shade(z, cmap=cmap, blend_mode=mode,\n                       vert_exag=ve, dx=dx, dy=dy)\n        ax.imshow(rgb)"}]},{"title":"Label the Plot","body":["We label the rows and columns of the plot grid using the set_title and set_ylabel functions. We also add a title for the vertical exaggeration and blend mode groups."],"code":[{"lang":"python","text":"for ax, ve in zip(axs[0], [0.1, 1, 10]):\n    ax.set_title(f'{ve}', size=18)\nfor ax, mode in zip(axs[:, 0], ['Hillshade', 'hsv', 'overlay', 'soft']):\n    ax.set_ylabel(mode, size=18)\n\naxs[0, 1].annotate('Vertical Exaggeration', (0.5, 1), xytext=(0, 30),\n                   textcoords='offset points', xycoords='axes fraction',\n                   ha='center', va='bottom', size=20)\naxs[2, 0].annotate('Blend Mode', (0, 0.5), xytext=(-30, 0),\n                   textcoords='offset points', xycoords='axes fraction',\n                   ha='right', va='center', size=20, rotation=90)\nfig.subplots_adjust(bottom=0.05, right=0.95)"}]},{"title":"Display the Plot","body":["Finally, we display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-offset-copy":{"intro":"In this lab, we will learn how to use transforms.offset_copy to position a drawing element, such as a text string, at a specified offset in screen coordinates relative to a location given in any coordinates. We will use the Matplotlib library in Python to create a scatter plot and a polar plot, and then add text to each plot using offset_copy.","steps":[{"title":"Import Libraries","body":["We will start by importing the necessary libraries: numpy and matplotlib.pyplot."],"code":[{"lang":"python","text":"import numpy as np\nimport matplotlib.pyplot as plt"}]},{"title":"Create Data","body":["Next, we will create some data to use in our plots. We will use numpy to create two arrays, xs and ys, that we will use as the x and y coordinates for our scatter plot."],"code":[{"lang":"python","text":"xs = np.arange(7)\nys = xs**2"}]},{"title":"Create a Scatter Plot","body":["We will now create a scatter plot using the plot function from matplotlib.pyplot."],"code":[{"lang":"python","text":"fig = plt.figure(figsize=(5, 10))\nax = plt.subplot(2, 1, 1)\n\n# Plot the data\nfor x, y in zip(xs, ys):\n    plt.plot(x, y, 'ro')"}]},{"title":"Add Text to the Scatter Plot","body":["Now we will add text to our scatter plot using offset_copy. We will first create a transform that positions the text at a specified offset in screen coordinates relative to a location given in any coordinates. Then, we will use the text function from matplotlib.pyplot to add the text to the plot."],"code":[{"lang":"python","text":"# Create the transform\ntrans_offset = mtransforms.offset_copy(ax.transData, fig=fig,\n                                       x=0.05, y=0.10, units='inches')\n\n# Add text to the plot\nfor x, y in zip(xs, ys):\n    plt.text(x, y, '%d, %d' % (int(x), int(y)), transform=trans_offset)"}]},{"title":"Create a Polar Plot","body":["We will now create a polar plot using the polar function from matplotlib.pyplot."],"code":[{"lang":"python","text":"ax = plt.subplot(2, 1, 2, projection='polar')\n\n# Plot the data\nfor x, y in zip(xs, ys):\n    plt.polar(x, y, 'ro')"}]},{"title":"Add Text to the Polar Plot","body":["Finally, we will add text to our polar plot using offset_copy and the text function from matplotlib.pyplot."],"code":[{"lang":"python","text":"# Create the transform\ntrans_offset = mtransforms.offset_copy(ax.transData, fig=fig,\n                                       y=6, units='dots')\n\n# Add text to the plot\nfor x, y in zip(xs, ys):\n    plt.text(x, y, '%d, %d' % (int(x), int(y)),\n             transform=trans_offset,\n             horizontalalignment='center',\n             verticalalignment='bottom')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Create the transform\ntrans_offset = mtransforms.offset_copy(ax.transData, fig=fig,\n                                       y=6, units='dots')\n\n# Add text to the plot\nfor x, y in zip(xs, ys):\n    plt.text(x, y, '%d, %d' % (int(x), int(y)),\n             transform=trans_offset,\n             horizontalalignment='center',\n             verticalalignment='bottom')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-contour-plotting-unstructured-triangular-gri":{"intro":"Contour plots are a way to represent three-dimensional data on a two-dimensional plane. In this tutorial, we will learn how to create contour plots of unstructured triangular grids using matplotlib and numpy.","steps":[{"title":"Create the Data","body":["First, we will create the x and y coordinates of the points, as well as the z values. We will use the np.linspace function to create evenly spaced arrays of values."],"code":[{"lang":"python","text":"n_angles = 48\nn_radii = 8\nmin_radius = 0.25\nradii = np.linspace(min_radius, 0.95, n_radii)\n\nangles = np.linspace(0, 2 * np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi / n_angles\n\nx = (radii * np.cos(angles)).flatten()\ny = (radii * np.sin(angles)).flatten()\nz = (np.cos(radii) * np.cos(3 * angles)).flatten()"}]},{"title":"Create the Triangulation","body":["We will create the triangulation using matplotlib.tri.Triangulation. We do not need to specify the triangles, so the Delaunay triangulation of the points will be created automatically."],"code":[{"lang":"python","text":"triang = tri.Triangulation(x, y)"}]},{"title":"Mask off unwanted triangles","body":["We will use the set_mask method to mask off unwanted triangles."],"code":[{"lang":"python","text":"triang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Create a pcolor plot","body":["We will create a pcolor plot using ax.tricontourf and fig.colorbar."],"code":[{"lang":"python","text":"fig1, ax1 = plt.subplots()\nax1.set_aspect('equal')\ntcf = ax1.tricontourf(triang, z)\nfig1.colorbar(tcf)\nax1.tricontour(triang, z, colors='k')\nax1.set_title('Contour plot of Delaunay triangulation')"}]},{"title":"Create a hatched contour plot","body":["We can create a hatched contour plot by specifying the hatches parameter in ax.tricontourf. We can also use a different colormap by specifying the cmap parameter."],"code":[{"lang":"python","text":"fig2, ax2 = plt.subplots()\nax2.set_aspect(\"equal\")\ntcf = ax2.tricontourf(\n    triang,\n    z,\n    hatches=[\"*\", \"-\", \"/\", \"//\", \"\\\\\", None],\n    cmap=\"cividis\"\n)\nfig2.colorbar(tcf)\nax2.tricontour(triang, z, linestyles=\"solid\", colors=\"k\", linewidths=2.0)\nax2.set_title(\"Hatched Contour plot of Delaunay triangulation\")"}]},{"title":"Generate hatching patterns labeled with no color","body":["Generate hatching patterns labeled with no color","We can generate hatching patterns labeled with no color by specifying the colors parameter as \"none\" in ax.tricontourf. We can also create a legend for the contour set using ContourSet.legend_elements."],"code":[{"lang":"python","text":"fig3, ax3 = plt.subplots()\nn_levels = 7\ntcf = ax3.tricontourf(\n    triang,\n    z,\n    n_levels,\n    colors=\"none\",\n    hatches=[\".\", \"/\", \"\\\\\", None, \"\\\\\\\\\", \"*\"],\n)\nax3.tricontour(triang, z, n_levels, colors=\"black\", linestyles=\"-\")\n\nartists, labels = tcf.legend_elements(str_format=\"{:2.1f}\".format)\nax3.legend(artists, labels, handleheight=2, framealpha=1)"}]},{"title":"Create a user-specified triangulation","body":["Create a user-specified triangulation","We can create a user-specified triangulation using the x, y, and triangles arrays. We can then create a contour plot using ax.tricontourf."],"code":[{"lang":"python","text":"xy = np.asarray([\n    [-0.101, 0.872], [-0.080, 0.883], [-0.069, 0.888], [-0.054, 0.890],\n    [-0.045, 0.897], [-0.057, 0.895], [-0.073, 0.900], [-0.087, 0.898],\n    [-0.090, 0.904], [-0.069, 0.907], [-0.069, 0.921], [-0.080, 0.919],\n    [-0.073, 0.928], [-0.052, 0.930], [-0.048, 0.942], [-0.062, 0.949],\n    [-0.054, 0.958], [-0.069, 0.954], [-0.087, 0.952], [-0.087, 0.959],\n    [-0.080, 0.966], [-0.085, 0.973], [-0.087, 0.965], [-0.097, 0.965],\n    [-0.097, 0.975], [-0.092, 0.984], [-0.101, 0.980], [-0.108, 0.980],\n    [-0.104, 0.987], [-0.102, 0.993], [-0.115, 1.001], [-0.099, 0.996],\n    [-0.101, 1.007], [-0.090, 1.010], [-0.087, 1.021], [-0.069, 1.021],\n    [-0.052, 1.022], [-0.052, 1.017], [-0.069, 1.010], [-0.064, 1.005],\n    [-0.048, 1.005], [-0.031, 1.005], [-0.031, 0.996], [-0.040, 0.987],\n    [-0.045, 0.980], [-0.052, 0.975], [-0.040, 0.973], [-0.026, 0.968],\n    [-0.020, 0.954], [-0.006, 0.947], [ 0.003, 0.935], [ 0.006, 0.926],\n    [ 0.005, 0.921], [ 0.022, 0.923], [ 0.033, 0.912], [ 0.029, 0.905],\n    [ 0.017, 0.900], [ 0.012, 0.895], [ 0.027, 0.893], [ 0.019, 0.886],\n    [ 0.001, 0.883], [-0.012, 0.884], [-0.029, 0.883], [-0.038, 0.879],\n    [-0.057, 0.881], [-0.062, 0.876], [-0.078, 0.876], [-0.087, 0.872],\n    [-0.030, 0.907], [-0.007, 0.905], [-0.057, 0.916], [-0.025, 0.933],\n    [-0.077, 0.990], [-0.059, 0.993]])\nx = np.degrees(xy[:, 0])\ny = np.degrees(xy[:, 1])\nx0 = -5\ny0 = 52\nz = np.exp(-0.01 * ((x - x0) ** 2 + (y - y0) ** 2))\n\ntriangles = np.asarray([\n    [67, 66,  1], [65,  2, 66], [ 1, 66,  2], [64,  2, 65], [63,  3, 64],\n    [60, 59, 57], [ 2, 64,  3], [ 3, 63,  4], [ 0, 67,  1], [62,  4, 63],\n    [57, 59, 56], [59, 58, 56], [61, 60, 69], [57, 69, 60], [ 4, 62, 68],\n    [ 6,  5,  9], [61, 68, 62], [69, 68, 61], [ 9,  5, 70], [ 6,  8,  7],\n    [ 4, 70,  5], [ 8,  6,  9], [56, 69, 57], [69, 56, 52], [70, 10,  9],\n    [54, 53, 55], [56, 55, 53], [68, 70,  4], [52, 56, 53], [11, 10, 12],\n    [69, 71, 68], [68, 13, 70], [10, 70, 13], [51, 50, 52], [13, 68, 71],\n    [52, 71, 69], [12, 10, 13], [71, 52, 50], [71, 14, 13], [50, 49, 71],\n    [49, 48, 71], [14, 16, 15], [14, 71, 48], [17, 19, 18], [17, 20, 19],\n    [48, 16, 14], [48, 47, 16], [47, 46, 16], [16, 46, 45], [23, 22, 24],\n    [21, 24, 22], [17, 16, 45], [20, 17, 45], [21, 25, 24], [27, 26, 28],\n    [20, 72, 21], [25, 21, 72], [45, 72, 20], [25, 28, 26], [44, 73, 45],\n    [72, 45,…"}]},{"title":"Show the plots","body":["Finally, we will show all the plots using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-tricontour-smooth-delaunay":{"intro":"This tutorial demonstrates how to generate high-resolution tricontouring plots with Matplotlib. Tricontouring is a technique used to represent data on an unstructured triangular mesh. It is often used when data is collected at irregularly spaced points, or when the data is inherently triangular in nature. The tutorial will show how to generate a random set of points, perform a Delaunay triangulation on those points, mask out some of the triangles in the mesh, refine and interpolate the data, and finally plot the refined data using Matplotlib's tricontour function.","steps":[{"title":"Import Required Libraries","body":["The first step is to import the required libraries. This tutorial will use NumPy and Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.tri import TriAnalyzer, Triangulation, UniformTriRefiner"}]},{"title":"Define Test Function","body":["Next, we define a function that represents the results of an experiment. This function will be used to generate the test data points."],"code":[{"lang":"python","text":"def experiment_res(x, y):\n    \"\"\"An analytic function representing experiment results.\"\"\"\n    x = 2 * x\n    r1 = np.sqrt((0.5 - x)**2 + (0.5 - y)**2)\n    theta1 = np.arctan2(0.5 - x, 0.5 - y)\n    r2 = np.sqrt((-x - 0.2)**2 + (-y - 0.2)**2)\n    theta2 = np.arctan2(-x - 0.2, -y - 0.2)\n    z = (4 * (np.exp((r1/10)**2) - 1) * 30 * np.cos(3 * theta1) +\n         (np.exp((r2/10)**2) - 1) * 30 * np.cos(5 * theta2) +\n         2 * (x**2 + y**2))\n    return (np.max(z) - z) / (np.max(z) - np.min(z))"}]},{"title":"Generate Test Data Points","body":["We generate a set of random test data points, with x and y values between -1 and 1. We also generate a corresponding set of z values using the experiment_res function defined in step 2."],"code":[{"lang":"python","text":"# User parameters for data test points\n\n# Number of test data points, tested from 3 to 5000 for subdiv=3\nn_test = 200\n\n# Random points\nrandom_gen = np.random.RandomState(seed=19680801)\nx_test = random_gen.uniform(-1., 1., size=n_test)\ny_test = random_gen.uniform(-1., 1., size=n_test)\nz_test = experiment_res(x_test, y_test)"}]},{"title":"Perform Delaunay Triangulation","body":["Perform Delaunay Triangulation","We perform a Delaunay triangulation on the test data points using the Triangulation function from the matplotlib.tri module."],"code":[{"lang":"python","text":"# meshing with Delaunay triangulation\ntri = Triangulation(x_test, y_test)\nntri = tri.triangles.shape[0]"}]},{"title":"Mask Some Triangles","body":["We mask out some of the triangles in the mesh to simulate invalidated data. We randomly select a subset of triangles based on the init_mask_frac parameter."],"code":[{"lang":"python","text":"# Some invalid data are masked out\nmask_init = np.zeros(ntri, dtype=bool)\nmasked_tri = random_gen.randint(0, ntri, int(ntri * init_mask_frac))\nmask_init[masked_tri] = True\ntri.set_mask(mask_init)"}]},{"title":"Improve Triangulation","body":["We use a TriAnalyzer to improve the triangulation by removing badly shaped (flat) triangles from the border of the triangulation. We then apply the mask to the triangulation using set_mask."],"code":[{"lang":"python","text":"# masking badly shaped triangles at the border of the triangular mesh.\nmask = TriAnalyzer(tri).get_flat_tri_mask(min_circle_ratio)\ntri.set_mask(mask)"}]},{"title":"Refine and Interpolate Data","body":["We refine and interpolate the data using a UniformTriRefiner."],"code":[{"lang":"python","text":"# refining the data\nrefiner = UniformTriRefiner(tri)\ntri_refi, z_test_refi = refiner.refine_field(z_test, subdiv=subdiv)"}]},{"title":"Plot the Data","body":["We plot the refined data using Matplotlib's tricontour function."],"code":[{"lang":"python","text":"# Graphical options for tricontouring\nlevels = np.arange(0., 1., 0.025)\n\nfig, ax = plt.subplots()\nax.set_aspect('equal')\nax.set_title(\"Filtering a Delaunay mesh\\n\"\n             \"(application to high-resolution tricontouring)\")\n\n# plot of the refined (computed) data contours:\nax.tricontour(tri_refi, z_test_refi, levels=levels, cmap='Blues',\n              linewidths=[2.0, 0.5, 1.0, 0.5])\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Graphical options for tricontouring\nlevels = np.arange(0., 1., 0.025)\n\nfig, ax = plt.subplots()\nax.set_aspect('equal')\nax.set_title(\"Filtering a Delaunay mesh\\n\"\n             \"(application to high-resolution tricontouring)\")\n\n# plot of the refined (computed) data contours:\nax.tricontour(tri_refi, z_test_refi, levels=levels, cmap='Blues',\n              linewidths=[2.0, 0.5, 1.0, 0.5])\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-tricontour-smooth-user":{"intro":"This lab will guide you through the process of creating high-resolution tricontours on user-defined triangular grids using Matplotlib. You will learn how to create a Triangulation, refine data, and plot the triangulation and high-resolution iso-contours.","steps":[{"title":"Analytical Test Function","body":["In this step, we define an analytical test function that will be used to generate z-values for the triangulation. The function is called function_z and takes two arguments, x and y. It calculates z based on the values of x and y, and returns the normalized z values."],"code":[{"lang":"python","text":"def function_z(x, y):\n    r1 = np.sqrt((0.5 - x)**2 + (0.5 - y)**2)\n    theta1 = np.arctan2(0.5 - x, 0.5 - y)\n    r2 = np.sqrt((-x - 0.2)**2 + (-y - 0.2)**2)\n    theta2 = np.arctan2(-x - 0.2, -y - 0.2)\n    z = -(2 * (np.exp((r1 / 10)**2) - 1) * 30. * np.cos(7. * theta1) +\n          (np.exp((r2 / 10)**2) - 1) * 30. * np.cos(11. * theta2) +\n          0.7 * (x**2 + y**2))\n    return (np.max(z) - z) / (np.max(z) - np.min(z))"}]},{"title":"Creating a Triangulation","body":["In this step, we create the x and y coordinates of the points using np.linspace and np.repeat. We then use the function_z defined in Step 1 to calculate the z-values. Finally, we create the Triangulation using tri.Triangulation."],"code":[{"lang":"python","text":"n_angles = 20\nn_radii = 10\nmin_radius = 0.15\nradii = np.linspace(min_radius, 0.95, n_radii)\n\nangles = np.linspace(0, 2 * np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi / n_angles\n\nx = (radii * np.cos(angles)).flatten()\ny = (radii * np.sin(angles)).flatten()\nz = function_z(x, y)\n\ntriang = tri.Triangulation(x, y)\ntriang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Refine Data","body":["In this step, we use tri.UniformTriRefiner to refine the data. We use the refine_field method to refine the z values and create a new Triangulation with higher resolution."],"code":[{"lang":"python","text":"refiner = tri.UniformTriRefiner(triang)\ntri_refi, z_test_refi = refiner.refine_field(z, subdiv=3)"}]},{"title":"Plot Triangulation and High-resolution Iso-contours","body":["Plot Triangulation and High-resolution Iso-contours","In this step, we plot the Triangulation and high-resolution iso-contours using ax.triplot, ax.tricontourf, and ax.tricontour."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_aspect('equal')\nax.triplot(triang, lw=0.5, color='white')\n\nlevels = np.arange(0., 1., 0.025)\nax.tricontourf(tri_refi, z_test_refi, levels=levels, cmap='terrain')\nax.tricontour(tri_refi, z_test_refi, levels=levels,\n              colors=['0.25', '0.5', '0.5', '0.5', '0.5'],\n              linewidths=[1.0, 0.5, 0.5, 0.5, 0.5])\n\nax.set_title(\"High-resolution tricontouring\")\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.set_aspect('equal')\nax.triplot(triang, lw=0.5, color='white')\n\nlevels = np.arange(0., 1., 0.025)\nax.tricontourf(tri_refi, z_test_refi, levels=levels, cmap='terrain')\nax.tricontour(tri_refi, z_test_refi, levels=levels,\n              colors=['0.25', '0.5', '0.5', '0.5', '0.5'],\n              linewidths=[1.0, 0.5, 0.5, 0.5, 0.5])\n\nax.set_title(\"High-resolution tricontouring\")\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-unstructured-triangular-grid-visualization":{"intro":"In this lab, we will create a triangular 3D contour plot using Matplotlib. This plot is useful for visualizing unstructured triangular grids. We will be using the same data as in the second plot of trisurf3d_2.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries for this lab, which include Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as tri"}]},{"title":"Define variables","body":["We will define the variables that we will use to create our plot. These variables include the number of angles, number of radii, and the minimum radius."],"code":[{"lang":"python","text":"n_angles = 48\nn_radii = 8\nmin_radius = 0.25"}]},{"title":"Create mesh and compute x, y, z","body":["Create mesh and compute x, y, z","We will create the mesh in polar coordinates and compute x, y, z using the defined variables."],"code":[{"lang":"python","text":"radii = np.linspace(min_radius, 0.95, n_radii)\nangles = np.linspace(0, 2*np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi/n_angles\n\nx = (radii*np.cos(angles)).flatten()\ny = (radii*np.sin(angles)).flatten()\nz = (np.cos(radii)*np.cos(3*angles)).flatten()"}]},{"title":"Create custom triangulation","body":["We will create a custom triangulation using the x and y coordinates."],"code":[{"lang":"python","text":"triang = tri.Triangulation(x, y)"}]},{"title":"Mask off unwanted triangles","body":["We will mask off the unwanted triangles using the mean of the x and y coordinates."],"code":[{"lang":"python","text":"triang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Create 3D contour plot","body":["We will create a 3D contour plot using the created triangulation and the z coordinates. We will also customize the view angle so it's easier to understand the plot."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.tricontour(triang, z, cmap=plt.cm.CMRmap)\nax.view_init(elev=45.)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.tricontour(triang, z, cmap=plt.cm.CMRmap)\nax.view_init(elev=45.)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-customized-3d-contour-plots":{"intro":"In this lab, you will learn how to create a triangular 3D filled contour plot using the Matplotlib library in Python. The plot will be created using unstructured triangular grids and customized triangulation. You will be able to control the view angle and color map of the plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries. In this case, we will need Matplotlib, Numpy, and Matplotlib Tri."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as tri"}]},{"title":"Create the Coordinates","body":["Next, we will create the x, y, z coordinates of the points. We will create the mesh in polar coordinates and compute x, y, z."],"code":[{"lang":"python","text":"n_angles = 48\nn_radii = 8\nmin_radius = 0.25\n\nradii = np.linspace(min_radius, 0.95, n_radii)\nangles = np.linspace(0, 2*np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi/n_angles\n\nx = (radii*np.cos(angles)).flatten()\ny = (radii*np.sin(angles)).flatten()\nz = (np.cos(radii)*np.cos(3*angles)).flatten()"}]},{"title":"Create a Custom Triangulation","body":["In this step, we will create a custom triangulation and mask off unwanted triangles."],"code":[{"lang":"python","text":"triang = tri.Triangulation(x, y)\ntriang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Create the Plot","body":["Now, we will create the plot using the tricontourf() function and customize the view angle."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.tricontourf(triang, z, cmap=plt.cm.CMRmap)\nax.view_init(elev=45.)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.tricontourf(triang, z, cmap=plt.cm.CMRmap)\nax.view_init(elev=45.)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-interactive-triangulation-plot-with-m":{"intro":"This lab will guide you through creating a triangulation plot using Matplotlib. You will learn how to create a Triangulation object, use a TriFinder object, and set up interactivity to highlight the triangle under the cursor.","steps":[{"title":"Create Triangulation Object","body":["First, we need to create a Triangulation object. We will use the Triangulation class from matplotlib.tri. In this example, we will create a Triangulation object with random data."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom matplotlib.tri import Triangulation\n\n# Generate random data\nx = np.random.rand(10)\ny = np.random.rand(10)\ntriang = Triangulation(x, y)"}]},{"title":"Create TriFinder Object","body":["To find the triangle under the cursor, we need to create a TriFinder object. We can get the default TriFinder object from the Triangulation object using the get_trifinder() method."],"code":[{"lang":"python","text":"trifinder = triang.get_trifinder()"}]},{"title":"Set up Plot","body":["Now, we can set up the plot. We will use plt.subplots() to create a figure and axis object. Then, we will use ax.triplot() to plot the triangulation."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.triplot(triang)"}]},{"title":"Highlight Triangle Under Cursor","body":["Highlight Triangle Under Cursor","We want to highlight the triangle under the cursor as the mouse is moved over the plot. To do this, we will create a Polygon object that will be updated with the vertices of the triangle under the cursor. We will use ax.add_patch() to add the polygon to the plot.","We will also create a function update_polygon() that will update the vertices of the polygon with the vertices of the triangle under the cursor."],"code":[{"lang":"python","text":"from matplotlib.patches import Polygon\n\npolygon = Polygon([[0, 0], [0, 0], [0, 0]], facecolor='y')\nax.add_patch(polygon)"},{"lang":"python","text":"def update_polygon(tri):\n    if tri == -1:\n        points = [0, 0, 0]\n    else:\n        points = triang.triangles[tri]\n    xs = triang.x[points]\n    ys = triang.y[points]\n    polygon.set_xy(np.column_stack([xs, ys]))"}]},{"title":"Set up Interactivity","body":["We need to set up interactivity to update the triangle under the cursor. We will use the motion_notify_event to detect when the mouse is moved over the plot. We will create a function on_mouse_move() that will get the triangle under the cursor using the TriFinder object, update the polygon with the vertices of the triangle, and update the plot title with the index of the triangle."],"code":[{"lang":"python","text":"def on_mouse_move(event):\n    if event.inaxes is None:\n        tri = -1\n    else:\n        tri = trifinder(event.xdata, event.ydata)\n    update_polygon(tri)\n    ax.set_title(f'Triangle {tri}')\n    event.canvas.draw()\n\nfig.canvas.mpl_connect('motion_notify_event', on_mouse_move)"}]},{"title":"Show Plot","body":["Finally, we can show the plot using plt.show()."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-electrical-dipole-gradient-visualization-wit":{"intro":"In this lab, you will learn how to use Matplotlib to create a gradient plot of an electrical dipole. You will learn how to create a triangulation, refine data, and compute the electrical field. Finally, you will plot the triangulation, the potential iso-contours, and the vector field.","steps":[{"title":"Create the x and y coordinates of the points","body":["Create the x and y coordinates of the points","• n_angles is the number of angles in a circle. • n_radii is the number of circles. • min_radius is the minimum radius of the circles. • radii is an array of radii. • angles is an array of angles. • x is an array of x-coordinates. • y is an array of y-coordinates."],"code":[{"lang":"python","text":"n_angles = 30\nn_radii = 10\nmin_radius = 0.2\nradii = np.linspace(min_radius, 0.95, n_radii)\n\nangles = np.linspace(0, 2 * np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi / n_angles\n\nx = (radii*np.cos(angles)).flatten()\ny = (radii*np.sin(angles)).flatten()"}]},{"title":"Compute the electrical potential of a dipole","body":["Compute the electrical potential of a dipole","• dipole_potential is a function that calculates the electrical dipole potential. • V is an array of electrical dipole potentials."],"code":[{"lang":"python","text":"def dipole_potential(x, y):\n    \"\"\"The electric dipole potential V, at position *x*, *y*.\"\"\"\n    r_sq = x**2 + y**2\n    theta = np.arctan2(y, x)\n    z = np.cos(theta)/r_sq\n    return (np.max(z) - z) / (np.max(z) - np.min(z))\n\nV = dipole_potential(x, y)"}]},{"title":"Create the Triangulation","body":["• Triangulation is a class that creates a Delaunay triangulation from a set of points. • triang is an instance of the Triangulation class. • triang.set_mask masks off unwanted triangles."],"code":[{"lang":"python","text":"triang = Triangulation(x, y)\n\ntriang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Refine data","body":["• UniformTriRefiner is a class that refines a triangulation to create a more accurate plot. • refiner is an instance of the UniformTriRefiner class. • tri_refi and z_test_refi are refined triangulation and potential values, respectively."],"code":[{"lang":"python","text":"refiner = UniformTriRefiner(triang)\ntri_refi, z_test_refi = refiner.refine_field(V, subdiv=3)"}]},{"title":"Compute the electrical field","body":["• CubicTriInterpolator is a class that interpolates data using a cubic polynomial. • tci is an instance of the CubicTriInterpolator class. • (Ex, Ey) is the electrical field. • E_norm is the normalized electrical field."],"code":[{"lang":"python","text":"tci = CubicTriInterpolator(triang, -V)\n\n(Ex, Ey) = tci.gradient(triang.x, triang.y)\nE_norm = np.sqrt(Ex**2 + Ey**2)"}]},{"title":"Plot the triangulation, the potential iso-contours, and the vector field","body":["Plot the triangulation, the potential iso-contours, and the vector field","• fig and ax are the figure and axes objects, respectively. • ax.set_aspect sets the aspect ratio of the axes. • ax.use_sticky_edges and ax.margins set the margins of the axes. • ax.triplot plots the triangulation. • ax.tricontour plots the potential iso-contours. • ax.quiver plots the vector field. • ax.set_title sets the title of the plot."],"code":[{"lang":"python","text":"fig, ax = plt.subplots()\nax.set_aspect('equal')\nax.use_sticky_edges = False\nax.margins(0.07)\n\nax.triplot(triang, color='0.8')\n\nlevels = np.arange(0., 1., 0.01)\nax.tricontour(tri_refi, z_test_refi, levels=levels, cmap='hot',\n              linewidths=[2.0, 1.0, 1.0, 1.0])\n\nax.quiver(triang.x, triang.y, Ex/E_norm, Ey/E_norm,\n          units='xy', scale=10., zorder=3, color='blue',\n          width=0.007, headwidth=3., headlength=4.)\n\nax.set_title('Gradient Plot: Electrical Dipole')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig, ax = plt.subplots()\nax.set_aspect('equal')\nax.use_sticky_edges = False\nax.margins(0.07)\n\nax.triplot(triang, color='0.8')\n\nlevels = np.arange(0., 1., 0.01)\nax.tricontour(tri_refi, z_test_refi, levels=levels, cmap='hot',\n              linewidths=[2.0, 1.0, 1.0, 1.0])\n\nax.quiver(triang.x, triang.y, Ex/E_norm, Ey/E_norm,\n          units='xy', scale=10., zorder=3, color='blue',\n          width=0.007, headwidth=3., headlength=4.)\n\nax.set_title('Gradient Plot: Electrical Dipole')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-pseudocolor-plots-with-matplotlib-t":{"intro":"This tutorial will guide you through creating pseudocolor plots of unstructured triangular grids using Python Matplotlib's tripcolor() function.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries for this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as tri"}]},{"title":"Creating a Delaunay Triangulation","body":["Creating a Delaunay Triangulation","We will create a Delaunay triangulation of the points. First, we will create the x and y coordinates of the points using NumPy.","Then, we will create the z coordinates of the points.","Next, we will create the Triangulation object using the Triangulation() function from matplotlib.tri. Since we are not specifying the triangles, the Delaunay triangulation will be created automatically."],"code":[{"lang":"python","text":"n_angles = 36\nn_radii = 8\nmin_radius = 0.25\nradii = np.linspace(min_radius, 0.95, n_radii)\nangles = np.linspace(0, 2 * np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi / n_angles\nx = (radii * np.cos(angles)).flatten()\ny = (radii * np.sin(angles)).flatten()"},{"lang":"python","text":"z = (np.cos(radii) * np.cos(3 * angles)).flatten()"},{"lang":"python","text":"triang = tri.Triangulation(x, y)"}]},{"title":"Create a Tripcolor Plot","body":["Now, we will create a tripcolor plot using the tripcolor() function. We will create two plots using different shading methods."],"code":[{"lang":"python","text":"# Flat shading plot\nfig1, ax1 = plt.subplots()\nax1.set_aspect('equal')\ntpc = ax1.tripcolor(triang, z, shading='flat')\nfig1.colorbar(tpc)\nax1.set_title('tripcolor of Delaunay triangulation, flat shading')\n\n# Gouraud shading plot\nfig2, ax2 = plt.subplots()\nax2.set_aspect('equal')\ntpc = ax2.tripcolor(triang, z, shading='gouraud')\nfig2.colorbar(tpc)\nax2.set_title('tripcolor of Delaunay triangulation, gouraud shading')"}]},{"title":"Create a User-Specified Triangulation","body":["Create a User-Specified Triangulation","We can also specify our own triangulation using the x, y, and triangles arrays. In this example, we will create a user-specified triangulation using the tripcolor() function.","Then, we will create the z coordinates of the faces using the mean() function.","Finally, we will create the tripcolor plot using the tripcolor() function and specifying the x, y, triangles, facecolors, and edgecolors."],"code":[{"lang":"python","text":"# Create x, y, and triangles arrays\nxy = np.asarray([\n    [-0.101, 0.872], [-0.080, 0.883], [-0.069, 0.888], [-0.054, 0.890],\n    [-0.045, 0.897], [-0.057, 0.895], [-0.073, 0.900], [-0.087, 0.898],\n    [-0.090, 0.904], [-0.069, 0.907], [-0.069, 0.921], [-0.080, 0.919],\n    [-0.073, 0.928], [-0.052, 0.930], [-0.048, 0.942], [-0.062, 0.949],\n    [-0.054, 0.958], [-0.069, 0.954], [-0.087, 0.952], [-0.087, 0.959],\n    [-0.080, 0.966], [-0.085, 0.973], [-0.087, 0.965], [-0.097, 0.965],\n    [-0.097, 0.975], [-0.092, 0.984], [-0.101, 0.980], [-0.108, 0.980],\n    [-0.104, 0.987], [-0.102, 0.993], [-0.115, 1.001], [-0.099, 0.996],\n    [-0.101, 1.007], [-0.090, 1.010], [-0.087, 1.021], [-0.069, 1.021],\n    [-0.052, 1.022], [-0.052, 1.017], [-0.069, 1.010], [-0.064, 1.005],\n    [-0.048, 1.005], [-0.031, 1.005], [-0.031, 0.996], [-0.040, 0.987],\n    [-0.045, 0.980], [-0.052, 0.975], [-0.040, 0.973], [-0.026, 0.968],\n    [-0.020, 0.954], [-0.006, 0.947], [ 0.003, 0.935], [ 0.006, 0.926],\n    [ 0.005, 0.921], [ 0.022, 0.923], [ 0.033, 0.912], [ 0.029, 0.905],\n    [ 0.017, 0.900], [ 0.012, 0.895], [ 0.027, 0.893], [ 0.019, 0.886],\n    [ 0.001, 0.883], [-0.012, 0.884], [-0.029, 0.883], [-0.038, 0.879],\n    [-0.057, 0.881], [-0.062, 0.876], [-0.078, 0.876], [-0.087, 0.872],\n    [-0.030, 0.907], [-0.007, 0.905], [-0.057, 0.916], [-0.025, 0.933],\n    [-0.077, 0.990], [-0.059, 0.993]])\nx, y = np.rad2deg(xy).T\ntriangles = np.asarray([\n    [67, 66,  1], [65,  2, 66], [ 1, 66,  2], [64,  2, 65], [63,  3, 64],\n    [60, 59, 57], [ 2, 64,  3], [ 3, 63,  4], [ 0, 67,  1], [62,  4, 63],\n    [57, 59, 56], [59, 58, 56], [61, 60, 69], [57, 69, 60], [ 4, 62, 68],\n    [ 6,  5,  9], [61, 68, 62], [69, 68, 61], [ 9,  5, 70], [ 6,  8,  7],\n    [ 4, 70,  5], [ 8,  6,  9], [56, 69, 57], [69, 56, 52], [70, 10,  9],\n    [54, 53, 55], [56, 55, 53], [68, 70,  4], [52, 56, 53], [11, 10, 12],\n    [69, 71, 68], [68, 13, 70], [10, 70, 13], [51, 50, 52], [13, 68, 71],\n    [52, 71, 69], [12, 10, 13], [71, 52, 50], [71, 14, 13], [50, 49, 71],\n    [49, 48, 71], [14, 16, 15], [14, 71, 48], [17, 19, 18], [17, 20, 19],\n    [48, 16, 14], [48, 47, 16], [47, 46, 16], [16, 46, 45], [23, 22, 24],\n    [21, 24, 22], [17, 16, 45], [20, 17, 45], [21, 25, 24], [27, 26, 28],\n    [20, 72, 21], [25, 21, 72], [45, 72, 20], [25, 28, 26], [44, 73, 45],\n    [72, 45, 73], [28, 25, 29], [29, 25, 31], [43, 73, 44], [73, 43,…"},{"lang":"python","text":"xmid = x[triangles].mean(axis=1)\nymid = y[triangles].mean(axis=1)\nx0 = -5\ny0 = 52\nzfaces = np.exp(-0.01 * ((xmid - x0) * (xmid - x0) +\n                         (ymid - y0) * (ymid - y0)))"},{"lang":"python","text":"fig3, ax3 = plt.subplots()\nax3.set_aspect('equal')\ntpc = ax3.tripcolor(x, y, triangles, facecolors=zfaces, edgecolors='k')\nfig3.colorbar(tpc)\nax3.set_title('tripcolor of user-specified triangulation')\nax3.set_xlabel('Longitude (degrees)')\nax3.set_ylabel('Latitude (degrees)')"}]},{"title":"Plot the Results","body":["Finally, we will use the show() function to display the plots."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-and-plotting-triangular-grids":{"intro":"In this lab, we will learn how to create and plot unstructured triangular grids in Python using the Matplotlib library. We will start by creating a Delaunay triangulation of a set of points and then plot the triangulation. Next, we will specify our own triangulation by providing the indices of the three points that make up each triangle. Finally, we will plot the user-specified triangulation.","steps":[{"title":"Import Libraries","body":["We will start by importing the required libraries: Matplotlib, NumPy, and Matplotlib.tri."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as tri"}]},{"title":"Create Delaunay Triangulation","body":["We will create a Delaunay triangulation without specifying the triangles by providing x and y coordinates of the points."],"code":[{"lang":"python","text":"n_angles = 36\nn_radii = 8\nmin_radius = 0.25\nradii = np.linspace(min_radius, 0.95, n_radii)\nangles = np.linspace(0, 2 * np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi / n_angles\nx = (radii * np.cos(angles)).flatten()\ny = (radii * np.sin(angles)).flatten()\ntriang = tri.Triangulation(x, y)"}]},{"title":"Mask Unwanted Triangles","body":["We will mask off unwanted triangles by computing the mean of the x and y coordinates of the vertices of each triangle and comparing it to the minimum radius."],"code":[{"lang":"python","text":"triang.set_mask(np.hypot(x[triang.triangles].mean(axis=1),\n                         y[triang.triangles].mean(axis=1))\n                < min_radius)"}]},{"title":"Plot Delaunay Triangulation","body":["We will plot the triangulation using the triplot function."],"code":[{"lang":"python","text":"fig1, ax1 = plt.subplots()\nax1.set_aspect('equal')\nax1.triplot(triang, 'bo-', lw=1)\nax1.set_title('Triplot of Delaunay Triangulation')"}]},{"title":"Create User-Specified Triangulation","body":["Create User-Specified Triangulation","We will create a user-specified triangulation by providing the x and y coordinates of the vertices of each triangle."],"code":[{"lang":"python","text":"xy = np.asarray([\n    [-0.101, 0.872], [-0.080, 0.883], [-0.069, 0.888], [-0.054, 0.890],\n    [-0.045, 0.897], [-0.057, 0.895], [-0.073, 0.900], [-0.087, 0.898],\n    [-0.090, 0.904], [-0.069, 0.907], [-0.069, 0.921], [-0.080, 0.919],\n    [-0.073, 0.928], [-0.052, 0.930], [-0.048, 0.942], [-0.062, 0.949],\n    [-0.054, 0.958], [-0.069, 0.954], [-0.087, 0.952], [-0.087, 0.959],\n    [-0.080, 0.966], [-0.085, 0.973], [-0.087, 0.965], [-0.097, 0.965],\n    [-0.097, 0.975], [-0.092, 0.984], [-0.101, 0.980], [-0.108, 0.980],\n    [-0.104, 0.987], [-0.102, 0.993], [-0.115, 1.001], [-0.099, 0.996],\n    [-0.101, 1.007], [-0.090, 1.010], [-0.087, 1.021], [-0.069, 1.021],\n    [-0.052, 1.022], [-0.052, 1.017], [-0.069, 1.010], [-0.064, 1.005],\n    [-0.048, 1.005], [-0.031, 1.005], [-0.031, 0.996], [-0.040, 0.987],\n    [-0.045, 0.980], [-0.052, 0.975], [-0.040, 0.973], [-0.026, 0.968],\n    [-0.020, 0.954], [-0.006, 0.947], [ 0.003, 0.935], [ 0.006, 0.926],\n    [ 0.005, 0.921], [ 0.022, 0.923], [ 0.033, 0.912], [ 0.029, 0.905],\n    [ 0.017, 0.900], [ 0.012, 0.895], [ 0.027, 0.893], [ 0.019, 0.886],\n    [ 0.001, 0.883], [-0.012, 0.884], [-0.029, 0.883], [-0.038, 0.879],\n    [-0.057, 0.881], [-0.062, 0.876], [-0.078, 0.876], [-0.087, 0.872],\n    [-0.030, 0.907], [-0.007, 0.905], [-0.057, 0.916], [-0.025, 0.933],\n    [-0.077, 0.990], [-0.059, 0.993]])\nx = np.degrees(xy[:, 0])\ny = np.degrees(xy[:, 1])\ntriangles = np.asarray([\n    [67, 66,  1], [65,  2, 66], [ 1, 66,  2], [64,  2, 65], [63,  3, 64],\n    [60, 59, 57], [ 2, 64,  3], [ 3, 63,  4], [ 0, 67,  1], [62,  4, 63],\n    [57, 59, 56], [59, 58, 56], [61, 60, 69], [57, 69, 60], [ 4, 62, 68],\n    [ 6,  5,  9], [61, 68, 62], [69, 68, 61], [ 9,  5, 70], [ 6,  8,  7],\n    [ 4, 70,  5], [ 8,  6,  9], [56, 69, 57], [69, 56, 52], [70, 10,  9],\n    [54, 53, 55], [56, 55, 53], [68, 70,  4], [52, 56, 53], [11, 10, 12],\n    [69, 71, 68], [68, 13, 70], [10, 70, 13], [51, 50, 52], [13, 68, 71],\n    [52, 71, 69], [12, 10, 13], [71, 52, 50], [71, 14, 13], [50, 49, 71],\n    [49, 48, 71], [14, 16, 15], [14, 71, 48], [17, 19, 18], [17, 20, 19],\n    [48, 16, 14], [48, 47, 16], [47, 46, 16], [16, 46, 45], [23, 22, 24],\n    [21, 24, 22], [17, 16, 45], [20, 17, 45], [21, 25, 24], [27, 26, 28],\n    [20, 72, 21], [25, 21, 72], [45, 72, 20], [25, 28, 26], [44, 73, 45],\n    [72, 45, 73], [28, 25, 29], [29, 25, 31], [43, 73, 44], [73, 43, 40],\n    [72,…"}]},{"title":"Plot User-Specified Triangulation","body":["Plot User-Specified Triangulation","We will plot the user-specified triangulation using the triplot function."],"code":[{"lang":"python","text":"fig2, ax2 = plt.subplots()\nax2.set_aspect('equal')\nax2.triplot(x, y, triangles, 'go-', lw=1.0)\nax2.set_title('Triplot of User-Specified Triangulation')\nax2.set_xlabel('Longitude (degrees)')\nax2.set_ylabel('Latitude (degrees)')"}]}],"commands":[],"reference":[{"path":"reference.py","text":"fig2, ax2 = plt.subplots()\nax2.set_aspect('equal')\nax2.triplot(x, y, triangles, 'go-', lw=1.0)\nax2.set_title('Triplot of User-Specified Triangulation')\nax2.set_xlabel('Longitude (degrees)')\nax2.set_ylabel('Latitude (degrees)')"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-triangular-3d-surfaces":{"intro":"In this lab, we will learn how to create a 3D surface with a triangular mesh using Python Matplotlib library.","steps":[{"title":"Import Libraries","body":["First, we need to import the necessary libraries:"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Variables","body":["We will define the variables for the radii and angles:"],"code":[{"lang":"python","text":"n_radii = 8\nn_angles = 36"}]},{"title":"Create Radii and Angles Spaces","body":["Create Radii and Angles Spaces","We will create the radii and angles spaces using the linspace function:"],"code":[{"lang":"python","text":"# Make radii and angles spaces (radius r=0 omitted to eliminate duplication).\nradii = np.linspace(0.125, 1.0, n_radii)\nangles = np.linspace(0, 2*np.pi, n_angles, endpoint=False)[..., np.newaxis]"}]},{"title":"Convert Polar Coordinates to Cartesian Coordinates","body":["Convert Polar Coordinates to Cartesian Coordinates","We will convert the polar coordinates to Cartesian coordinates:"],"code":[{"lang":"python","text":"# Convert polar (radii, angles) coords to cartesian (x, y) coords.\n# (0, 0) is manually added at this stage, so there will be no duplicate\n# points in the (x, y) plane.\nx = np.append(0, (radii*np.cos(angles)).flatten())\ny = np.append(0, (radii*np.sin(angles)).flatten())"}]},{"title":"Compute Z to Make the Pringle Surface","body":["Compute Z to Make the Pringle Surface","We will compute z to make the pringle surface:"],"code":[{"lang":"python","text":"# Compute z to make the pringle surface.\nz = np.sin(-x*y)"}]},{"title":"Create the 3D Surface","body":["We will create the 3D surface using the plot_trisurf function:"],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.plot_trisurf(x, y, z, linewidth=0.2, antialiased=True)\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.plot_trisurf(x, y, z, linewidth=0.2, antialiased=True)\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-more-triangular-3d-surfaces":{"intro":"This tutorial demonstrates how to create 3D surfaces using triangular mesh in Python's Matplotlib library. It shows two examples of plotting surfaces with triangular mesh.","steps":[{"title":"Import Required Libraries","body":["We begin by importing the required libraries: matplotlib.pyplot and numpy. We also import matplotlib.tri to create the triangular meshes."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.tri as mtri"}]},{"title":"Create a Mesh","body":["We create a mesh in the space of parameterization variables u and v. This is done using the np.meshgrid() function to create a grid of u and v points."],"code":[{"lang":"python","text":"u = np.linspace(0, 2.0 * np.pi, endpoint=True, num=50)\nv = np.linspace(-0.5, 0.5, endpoint=True, num=10)\nu, v = np.meshgrid(u, v)\nu, v = u.flatten(), v.flatten()"}]},{"title":"Define the Surface","body":["Next, we define the surface. In this example, we use a Mobius mapping to take a u, v pair and return an x, y, z triple."],"code":[{"lang":"python","text":"x = (1 + 0.5 * v * np.cos(u / 2.0)) * np.cos(u)\ny = (1 + 0.5 * v * np.cos(u / 2.0)) * np.sin(u)\nz = 0.5 * v * np.sin(u / 2.0)"}]},{"title":"Triangulate Parameter Space","body":["We triangulate the parameter space to determine the triangles that will connect the x, y, z points."],"code":[{"lang":"python","text":"tri = mtri.Triangulation(u, v)"}]},{"title":"Plot the Surface","body":["Finally, we plot the surface using plot_trisurf() function. The triangles in parameter space determine which x, y, z points are connected by an edge."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.plot_trisurf(x, y, z, triangles=tri.triangles, cmap=plt.cm.Spectral)\nax.set_zlim(-1, 1)"}]},{"title":"Create a Mask","body":["In this example, we create a mask to remove unwanted triangles. We first create parameter spaces radii and angles."],"code":[{"lang":"python","text":"n_angles = 36\nn_radii = 8\nmin_radius = 0.25\nradii = np.linspace(min_radius, 0.95, n_radii)\n\nangles = np.linspace(0, 2*np.pi, n_angles, endpoint=False)\nangles = np.repeat(angles[..., np.newaxis], n_radii, axis=1)\nangles[:, 1::2] += np.pi/n_angles"}]},{"title":"Map to x, y, z Points","body":["We map the radius, angle pairs to x, y, z points."],"code":[{"lang":"python","text":"x = (radii*np.cos(angles)).flatten()\ny = (radii*np.sin(angles)).flatten()\nz = (np.cos(radii)*np.cos(3*angles)).flatten()"}]},{"title":"Create Triangulation","body":["We create the triangulation using the Triangulation() function. Since there are no triangles, the Delaunay triangulation is created."],"code":[{"lang":"python","text":"triang = mtri.Triangulation(x, y)"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.plot_trisurf(triang, z, cmap=plt.cm.CMRmap)"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-plots-with-different-scales":{"intro":"In this lab, you will learn how to create plots with different scales in Python using Matplotlib. Specifically, you will learn how to create two plots on the same axes with different left and right scales.","steps":[{"title":"Import Required Libraries","body":["Before we begin, let's import the required libraries. We will be using Matplotlib and NumPy for this tutorial."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create Some Mock Data","body":["Next, we will create some mock data to use for our plots. We will be using numpy.arange to create an array of values ranging from 0.01 to 10.0 with a step of 0.01. We will then use numpy.exp and numpy.sin to create two sets of data."],"code":[{"lang":"python","text":"# Create some mock data\nt = np.arange(0.01, 10.0, 0.01)\ndata1 = np.exp(t)\ndata2 = np.sin(2 * np.pi * t)"}]},{"title":"Create the Plot","body":["Now that we have our data, we can create our plot. We will begin by creating an axes object using matplotlib.pyplot.subplots(). We will then plot our first set of data on this axes object and set the label color to red.","Next, we will instantiate a second axes object that shares the same x-axis as the first axes object using the ax1.twinx() method. We will then plot our second set of data on this new axes object and set the label color to blue.","Finally, we will adjust the layout of our plot using the fig.tight_layout() method and display it using matplotlib.pyplot.show()."],"code":[{"lang":"python","text":"fig, ax1 = plt.subplots()\n\ncolor = 'tab:red'\nax1.set_xlabel('time (s)')\nax1.set_ylabel('exp', color=color)\nax1.plot(t, data1, color=color)\nax1.tick_params(axis='y', labelcolor=color)"},{"lang":"python","text":"ax2 = ax1.twinx()\n\ncolor = 'tab:blue'\nax2.set_ylabel('sin', color=color)\nax2.plot(t, data2, color=color)\nax2.tick_params(axis='y', labelcolor=color)"},{"lang":"python","text":"fig.tight_layout()\nplt.show()"}]},{"title":"Review the Plot","body":["Take a moment to review the plot that was created. Notice how the two sets of data have different scales on the y-axis. The first set of data is plotted in red and has a scale on the left side of the plot, while the second set of data is plotted in blue and has a scale on the right side of the plot."],"code":[]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-data-visualization":{"intro":"This lab is designed to introduce you to the basics of data visualization using Matplotlib. Matplotlib is a popular data visualization library for Python that provides a wide range of options for creating plots, graphs, and charts.","steps":[{"title":"Setting Up","body":["Before we start, we need to ensure that Matplotlib is installed. You can install it using pip, by running the following command:"],"code":[{"lang":"python","text":"!pip install matplotlib"},{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\n# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# Create new Figure with black background\nfig = plt.figure(figsize=(8, 8), facecolor='black')\n\n# Add a subplot with no frame\nax = plt.subplot(frameon=False)"}]},{"title":"Generating Random Data","body":["In this step, we will generate random data that we will use to create our plot."],"code":[{"lang":"python","text":"# Generate random data\ndata = np.random.uniform(0, 1, (64, 75))\nX = np.linspace(-1, 1, data.shape[-1])\nG = 1.5 * np.exp(-4 * X ** 2)"}]},{"title":"Creating Line Plots","body":["We will create line plots using the random data that we generated in the previous step."],"code":[{"lang":"python","text":"# Generate line plots\nlines = []\nfor i in range(len(data)):\n    # Small reduction of the X extents to get a cheap perspective effect\n    xscale = 1 - i / 200.\n    # Same for linewidth (thicker strokes on bottom)\n    lw = 1.5 - i / 100.0\n    line, = ax.plot(xscale * X, i + G * data[i], color=\"w\", lw=lw)\n    lines.append(line)"}]},{"title":"Setting Limits and Removing Ticks","body":["Setting Limits and Removing Ticks","In this step, we will set the y limit and remove the ticks from the plot."],"code":[{"lang":"python","text":"# Set y limit (or first line is cropped because of thickness)\nax.set_ylim(-1, 70)\n\n# No ticks\nax.set_xticks([])\nax.set_yticks([])"}]},{"title":"Adding Title","body":["We will add a title to our plot."],"code":[{"lang":"python","text":"# 2 part titles to get different font weights\nax.text(0.5, 1.0, \"MATPLOTLIB \", transform=ax.transAxes,\n        ha=\"right\", va=\"bottom\", color=\"w\",\n        family=\"sans-serif\", fontweight=\"light\", fontsize=16)\nax.text(0.5, 1.0, \"UNCHAINED\", transform=ax.transAxes,\n        ha=\"left\", va=\"bottom\", color=\"w\",\n        family=\"sans-serif\", fontweight=\"bold\", fontsize=16)"}]},{"title":"Animating the Plot","body":["We will now animate the plot by shifting the data to the right and filling in new values."],"code":[{"lang":"python","text":"import matplotlib.animation as animation\n\ndef update(*args):\n    # Shift all data to the right\n    data[:, 1:] = data[:, :-1]\n\n    # Fill-in new values\n    data[:, 0] = np.random.uniform(0, 1, len(data))\n\n    # Update data\n    for i in range(len(data)):\n        lines[i].set_ydata(i + G * data[i])\n\n    # Return modified artists\n    return lines\n\n# Construct the animation, using the update function as the animation director.\nanim = animation.FuncAnimation(fig, update, interval=10, save_count=100)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"import matplotlib.animation as animation\n\ndef update(*args):\n    # Shift all data to the right\n    data[:, 1:] = data[:, :-1]\n\n    # Fill-in new values\n    data[:, 0] = np.random.uniform(0, 1, len(data))\n\n    # Update data\n    for i in range(len(data)):\n        lines[i].set_ydata(i + G * data[i])\n\n    # Return modified artists\n    return lines\n\n# Construct the animation, using the update function as the animation director.\nanim = animation.FuncAnimation(fig, update, interval=10, save_count=100)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-controlling-matplotlib-tick-labels-with-unic":{"intro":"In this lab, we will learn how to control the tick labels in a Matplotlib plot using Unicode minus and ASCII hyphen. By default, tick labels at negative values are rendered using a Unicode minus rather than an ASCII hyphen. However, this can be controlled by setting axes.unicode_minus. We will use a sample code snippet to showcase the difference between the two glyphs in a magnified font.","steps":[{"title":"Importing the Required Libraries","body":["Importing the Required Libraries","We will start by importing the required libraries matplotlib.pyplot and numpy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Setting up the Data","body":["Next, we will create some sample data to plot using the numpy library. We will create a linearly spaced array of 100 values between 0 and 10."],"code":[{"lang":"python","text":"x = np.linspace(0, 10, 100)"}]},{"title":"Plotting the Data","body":["Now, we will plot the data using the plot function of Matplotlib. We will plot a sine wave with a frequency of 1 and amplitude of 1."],"code":[{"lang":"python","text":"y = np.sin(x)\nplt.plot(x, y)"}]},{"title":"Setting the Tick Labels","body":["By default, tick labels at negative values are rendered using a Unicode minus rather than an ASCII hyphen. However, we can change this behavior by setting axes.unicode_minus to False."],"code":[{"lang":"python","text":"plt.rcParams['axes.unicode_minus'] = False"}]},{"title":"Displaying the Plot","body":["Finally, we will display the plot using the show function of Matplotlib."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-converting-units-of-axis-in-python":{"intro":"In data visualization, it is important to have the correct units of measurement on the axes of the plot. This tutorial demonstrates how to convert the units of the x and y axes in Matplotlib using Python.","steps":[{"title":"Import the Required Libraries","body":["First, import the required libraries. In this example, we will use Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the Units","body":["Next, define the units for the x and y axes. In this example, we will use centimeters and inches. We can use the basic_units library to define the units."],"code":[{"lang":"python","text":"from basic_units import cm, inch"}]},{"title":"Create Data","body":["Now, create some data to plot. In this example, we will use np.arange to create an array of values from 0 to 8 in increments of 2."],"code":[{"lang":"python","text":"cms = cm * np.arange(0, 10, 2)"}]},{"title":"Create the Plot","body":["Create a 2x2 grid of subplots using the subplots function. Then, use the plot function to plot the data on each subplot."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(2, 2, layout='constrained')\n\naxs[0, 0].plot(cms, cms)\n\naxs[0, 1].plot(cms, cms, xunits=cm, yunits=inch)\n\naxs[1, 0].plot(cms, cms, xunits=inch, yunits=cm)\naxs[1, 0].set_xlim(-1, 4)  # scalars are interpreted in current units\n\naxs[1, 1].plot(cms, cms, xunits=inch, yunits=inch)\naxs[1, 1].set_xlim(3*cm, 6*cm)  # cm are converted to inches"}]},{"title":"Display the Plot","body":["Finally, display the plot using the show function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-python-matplotlib-unit-conversions":{"intro":"This lab will guide you through a step-by-step tutorial on how to perform unit conversions over masked arrays using Python Matplotlib.","steps":[{"title":"Import Libraries","body":["In this step, we will import the necessary libraries to perform the unit conversions and plotting."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nfrom basic_units import hertz, minutes, secs"}]},{"title":"Create Masked Array","body":["In this step, we will create a masked array and apply the mask to the data."],"code":[{"lang":"python","text":"# create masked array\ndata = (1, 2, 3, 4, 5, 6, 7, 8)\nmask = (1, 0, 1, 0, 0, 0, 1, 0)\nxsecs = secs * np.ma.MaskedArray(data, mask, float)"}]},{"title":"Create Plots","body":["In this step, we will create three plots using the masked array with different units."],"code":[{"lang":"python","text":"# create subplots\nfig, (ax1, ax2, ax3) = plt.subplots(nrows=3, sharex=True)\n\n# plot 1\nax1.scatter(xsecs, xsecs)\nax1.yaxis.set_units(secs)\n\n# plot 2\nax2.scatter(xsecs, xsecs, yunits=hertz)\n\n# plot 3\nax3.scatter(xsecs, xsecs, yunits=minutes)\n\n# set labels\nax1.set_ylabel('Seconds')\nax2.set_ylabel('Hertz')\nax3.set_ylabel('Minutes')\nax3.set_xlabel('Time')"}]},{"title":"Display Plots","body":["In this step, we will display the plots that were created in the previous step."],"code":[{"lang":"python","text":"# display plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# display plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-text-baselines-comparison":{"intro":"In this lab, we will compare the text baselines computed for mathtext and usetex using Matplotlib library. We will create a plot that contains two subplots, one with mathtext and the other with usetex. Each subplot will display four test strings with different styles and positions.","steps":[{"title":"Import the necessary libraries","body":["Import the necessary libraries","We need to import the matplotlib.pyplot library to create the plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Set the Matplotlib font","body":["We need to set the font to be used for Matplotlib text. We will use the Computer Modern font and set it as the default font for Matplotlib."],"code":[{"lang":"python","text":"plt.rcParams.update({\"mathtext.fontset\": \"cm\", \"mathtext.rm\": \"serif\"})"}]},{"title":"Create the subplots","body":["We will create a figure that contains two subplots, one with mathtext and the other with usetex. We will use the subplots() method to create the subplots."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(1, 2, figsize=(2 * 3, 6.5))"}]},{"title":"Add test strings to the plot","body":["We will add four test strings to each subplot, each with a different style and position. We will use the text() method to add the text to the subplots."],"code":[{"lang":"python","text":"test_strings = [\"lg\", r\"$\\frac{1}{2}\\pi$\", r\"$p^{3^A}$\", r\"$p_{3_2}$\"]\nfor ax, usetex in zip(axs, [False, True]):\n    ax.axvline(0, color=\"r\")\n    for i, s in enumerate(test_strings):\n        ax.axhline(i, color=\"r\")\n        ax.text(0., 3 - i, s,\n                usetex=usetex,\n                verticalalignment=\"baseline\",\n                size=50,\n                bbox=dict(pad=0, ec=\"k\", fc=\"none\"))"}]},{"title":"Set the plot limits and labels","body":["Set the plot limits and labels","We will set the plot limits and labels to match the desired output."],"code":[{"lang":"python","text":"for ax in axs:\n    ax.set(xlim=(-0.1, 1.1), ylim=(-.8, 3.9), xticks=[], yticks=[])\n    ax.set_title(f\"usetex={ax.usetex}\\n\")"}]},{"title":"Display the plot","body":["We will display the plot using the show() method."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-usetex-font-effects":{"intro":"This tutorial will walk you through how to apply font effects to your Matplotlib plots using the usetex mode. We will use a sample script that demonstrates font effects specified in the pdftex.map file. By the end of this tutorial, you will be able to create professional-looking plots with custom font effects.","steps":[{"title":"Install Matplotlib","body":["Before we begin, we need to make sure that Matplotlib is installed. You can install it using pip:"],"code":[{"lang":"text","text":"pip install matplotlib"}]},{"title":"Import the Required Libraries","body":["In this step, we will import the required libraries for this tutorial. We will be using the Matplotlib library to create our plot."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Define the Font Function","body":["In this step, we will define a function that sets the font. This function takes a font name as an argument and returns a string that sets the font to the specified name."],"code":[{"lang":"python","text":"def setfont(font):\n    return rf'\\font\\a {font} at 14pt\\a '"}]},{"title":"Create the Plot","body":["In this step, we will create the plot. We will use the fig.text() method to add text to the plot. We will iterate over a list of fonts and corresponding text, using the zip() function to match them up. We will set the usetex parameter to True to enable the usetex mode."],"code":[{"lang":"python","text":"fig = plt.figure()\nfor y, font, text in zip(\n    range(5),\n    ['ptmr8r', 'ptmri8r', 'ptmro8r', 'ptmr8rn', 'ptmrr8re'],\n    [f'Nimbus Roman No9 L {x}'\n     for x in ['', 'Italics (real italics for comparison)',\n               '(slanted)', '(condensed)', '(extended)']],\n):\n    fig.text(.1, 1 - (y + 1) / 6, setfont(font) + text, usetex=True)\n\nfig.suptitle('Usetex font effects')\nplt.show()"}]},{"title":"Interpret the Results","body":["The script creates a plot that demonstrates font effects specified in the pdftex.map file. It shows how you can use different fonts and font styles to create custom text on your plot."],"code":[]}],"commands":["pip install matplotlib"],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-primary-3d-view-planes":{"intro":"In this tutorial, we will learn how to generate an 'unfolded' 3D plot using Matplotlib that shows each of the primary 3D view planes. We will also label the elevation, azimuth, and roll angles required for each view. This image can be printed out and folded into a box where each plane forms a side of the box.","steps":[{"title":"Import necessary libraries","body":["We start by importing the necessary libraries for this tutorial, which includes Matplotlib."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt"}]},{"title":"Define a function to annotate axes","body":["Define a function to annotate axes","We define a function annotate_axes that we will use later to label each of the primary 3D view planes with their respective angles."],"code":[{"lang":"python","text":"def annotate_axes(ax, text, fontsize=18):\n    ax.text(x=0.5, y=0.5, z=0.5, s=text,\n            va=\"center\", ha=\"center\", fontsize=fontsize, color=\"black\")"}]},{"title":"Define the primary 3D view planes and their angles","body":["Define the primary 3D view planes and their angles","We define the primary 3D view planes and their corresponding elevation, azimuth, and roll angles."],"code":[{"lang":"python","text":"views = [('XY',   (90, -90, 0)),\n         ('XZ',    (0, -90, 0)),\n         ('YZ',    (0,   0, 0)),\n         ('-XY', (-90,  90, 0)),\n         ('-XZ',   (0,  90, 0)),\n         ('-YZ',   (0, 180, 0))]"}]},{"title":"Define the layout of the 3D plot","body":["Define the layout of the 3D plot","We define the layout of the 3D plot using a list of lists. The '.' in the list represents an empty subplot."],"code":[{"lang":"python","text":"layout = [['XY',  '.',   'L',   '.'],\n          ['XZ', 'YZ', '-XZ', '-YZ'],\n          ['.',   '.', '-XY',   '.']]"}]},{"title":"Create the 3D plot","body":["We use subplot_mosaic to create the 3D plot based on the layout defined in step 4."],"code":[{"lang":"python","text":"fig, axd = plt.subplot_mosaic(layout, subplot_kw={'projection': '3d'},\n                              figsize=(12, 8.5))"}]},{"title":"Set the properties of each primary 3D view plane","body":["Set the properties of each primary 3D view plane","We set the properties of each primary 3D view plane, including the labels for the x, y, and z axes, the projection type, and the view angles."],"code":[{"lang":"python","text":"for plane, angles in views:\n    axd[plane].set_xlabel('x')\n    axd[plane].set_ylabel('y')\n    axd[plane].set_zlabel('z')\n    axd[plane].set_proj_type('ortho')\n    axd[plane].view_init(elev=angles[0], azim=angles[1], roll=angles[2])\n    axd[plane].set_box_aspect(None, zoom=1.25)"}]},{"title":"Label each primary 3D view plane","body":["Label each primary 3D view plane","We use the annotate_axes function defined in step 2 to label each primary 3D view plane with its respective angles."],"code":[{"lang":"python","text":"for plane, angles in views:\n    label = f'{plane}\\n{angles}'\n    annotate_axes(axd[plane], label, fontsize=14)"}]},{"title":"Customize the tick labels and axis labels for each primary 3D view plane","body":["Customize the tick labels and axis labels for each primary 3D view plane","We customize the tick labels and axis labels for each primary 3D view plane to remove any unnecessary labels."],"code":[{"lang":"python","text":"for plane in ('XY', '-XY'):\n    axd[plane].set_zticklabels([])\n    axd[plane].set_zlabel('')\nfor plane in ('XZ', '-XZ'):\n    axd[plane].set_yticklabels([])\n    axd[plane].set_ylabel('')\nfor plane in ('YZ', '-YZ'):\n    axd[plane].set_xticklabels([])\n    axd[plane].set_xlabel('')"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-interactive-data-visualization-with-matplotl":{"intro":"In data visualization, zooming in on a specific area of a plot can be extremely useful to better understand and analyze the data. Matplotlib, a popular data visualization library for Python, provides a way to create two identical panels and zoom in on the right panel to show a rectangle in the first panel, denoting the zoomed region. In this lab, we will learn how to create this interactive zooming feature in Matplotlib.","steps":[{"title":"Import necessary libraries","body":["We will first import the necessary libraries, including Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\n\nfrom matplotlib.patches import Rectangle"}]},{"title":"Create the UpdatingRect class","body":["We will create a subclass of Rectangle called UpdatingRect. This class is called with an Axes instance, causing the rectangle to update its shape to match the bounds of the Axes."],"code":[{"lang":"python","text":"class UpdatingRect(Rectangle):\n    def __call__(self, ax):\n        self.set_bounds(*ax.viewLim.bounds)\n        ax.figure.canvas.draw_idle()"}]},{"title":"Create the MandelbrotDisplay class","body":["Create the MandelbrotDisplay class","We will create a class called MandelbrotDisplay that will regenerate a fractal set as we zoom in, so that we can actually see the increasing detail. A box in the left panel will show the area to which we are zoomed."],"code":[{"lang":"python","text":"class MandelbrotDisplay:\n    def __init__(self, h=500, w=500, niter=50, radius=2., power=2):\n        self.height = h\n        self.width = w\n        self.niter = niter\n        self.radius = radius\n        self.power = power\n\n    def compute_image(self, xstart, xend, ystart, yend):\n        self.x = np.linspace(xstart, xend, self.width)\n        self.y = np.linspace(ystart, yend, self.height).reshape(-1, 1)\n        c = self.x + 1.0j * self.y\n        threshold_time = np.zeros((self.height, self.width))\n        z = np.zeros(threshold_time.shape, dtype=complex)\n        mask = np.ones(threshold_time.shape, dtype=bool)\n        for i in range(self.niter):\n            z[mask] = z[mask]**self.power + c[mask]\n            mask = (np.abs(z) < self.radius)\n            threshold_time += mask\n        return threshold_time\n\n    def ax_update(self, ax):\n        ax.set_autoscale_on(False)\n        self.width, self.height = \\\n            np.round(ax.patch.get_window_extent().size).astype(int)\n        vl = ax.viewLim\n        extent = vl.x0, vl.x1, vl.y0, vl.y1\n        im = ax.images[-1]\n        im.set_data(self.compute_image(*extent))\n        im.set_extent(extent)\n        ax.figure.canvas.draw_idle()"}]},{"title":"Create the plot","body":["We will create the plot by first computing the image using the MandelbrotDisplay class, and then creating two identical panels using subplots. We will add the image to both panels using imshow, and add the UpdatingRect object to the left panel."],"code":[{"lang":"python","text":"md = MandelbrotDisplay()\nZ = md.compute_image(-2., 0.5, -1.25, 1.25)\n\nfig1, (ax1, ax2) = plt.subplots(1, 2)\nax1.imshow(Z, origin='lower',\n           extent=(md.x.min(), md.x.max(), md.y.min(), md.y.max()))\nax2.imshow(Z, origin='lower',\n           extent=(md.x.min(), md.x.max(), md.y.min(), md.y.max()))\n\nrect = UpdatingRect(\n    [0, 0], 0, 0, facecolor='none', edgecolor='black', linewidth=1.0)\nrect.set_bounds(*ax2.viewLim.bounds)\nax1.add_patch(rect)"}]},{"title":"Add zooming functionality","body":["We will add the zooming functionality by connecting the xlim_changed and ylim_changed events to the UpdatingRect and MandelbrotDisplay objects."],"code":[{"lang":"python","text":"ax2.callbacks.connect('xlim_changed', rect)\nax2.callbacks.connect('ylim_changed', rect)\n\nax2.callbacks.connect('xlim_changed', md.ax_update)\nax2.callbacks.connect('ylim_changed', md.ax_update)\nax2.set_title(\"Zoom here\")"}]},{"title":"Show the plot","body":["We will show the plot using the show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-violin-plotting-with-matplotlib":{"intro":"In this lab, we will learn how to create violin plots using Matplotlib library in Python. Violin plots are used to visualize the distribution of a dataset. These plots are similar to box plots, but instead of showing only the summary statistics, violin plots show the full distribution of the data.","steps":[{"title":"Import necessary libraries","body":["We will start by importing the necessary libraries to create the violin plots."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Create sample dataset","body":["We will create a sample dataset using numpy library. We will create six datasets with different standard deviations."],"code":[{"lang":"python","text":"# Fixing random state for reproducibility\nnp.random.seed(19680801)\n\n# fake data\npos = [1, 2, 4, 5, 7, 8]\ndata = [np.random.normal(0, std, size=100) for std in pos]"}]},{"title":"Create custom violin plots","body":["We will create custom violin plots by modifying various parameters. We will create 5 custom violin plots using different parameters."],"code":[{"lang":"python","text":"fig, axs = plt.subplots(nrows=2, ncols=5, figsize=(10, 6))\n\n# Custom violinplot 1\naxs[0, 0].violinplot(data, pos, points=20, widths=0.3,\n                     showmeans=True, showextrema=True, showmedians=True)\naxs[0, 0].set_title('Custom violinplot 1', fontsize=fs)\n\n# Custom violinplot 2\naxs[0, 1].violinplot(data, pos, points=40, widths=0.5,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     bw_method='silverman')\naxs[0, 1].set_title('Custom violinplot 2', fontsize=fs)\n\n# Custom violinplot 3\naxs[0, 2].violinplot(data, pos, points=60, widths=0.7, showmeans=True,\n                     showextrema=True, showmedians=True, bw_method=0.5)\naxs[0, 2].set_title('Custom violinplot 3', fontsize=fs)\n\n# Custom violinplot 4\naxs[0, 3].violinplot(data, pos, points=60, widths=0.7, showmeans=True,\n                     showextrema=True, showmedians=True, bw_method=0.5,\n                     quantiles=[[0.1], [], [], [0.175, 0.954], [0.75], [0.25]])\naxs[0, 3].set_title('Custom violinplot 4', fontsize=fs)\n\n# Custom violinplot 5\naxs[0, 4].violinplot(data[-1:], pos[-1:], points=60, widths=0.7,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     quantiles=[0.05, 0.1, 0.8, 0.9], bw_method=0.5)\naxs[0, 4].set_title('Custom violinplot 5', fontsize=fs)"}]},{"title":"Create more custom violin plots","body":["Create more custom violin plots","We will create more custom violin plots using different parameters."],"code":[{"lang":"python","text":"# Custom violinplot 6\naxs[1, 0].violinplot(data, pos, points=80, vert=False, widths=0.7,\n                     showmeans=True, showextrema=True, showmedians=True)\naxs[1, 0].set_title('Custom violinplot 6', fontsize=fs)\n\n# Custom violinplot 7\naxs[1, 1].violinplot(data, pos, points=100, vert=False, widths=0.9,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     bw_method='silverman')\naxs[1, 1].set_title('Custom violinplot 7', fontsize=fs)\n\n# Custom violinplot 8\naxs[1, 2].violinplot(data, pos, points=200, vert=False, widths=1.1,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     bw_method=0.5)\naxs[1, 2].set_title('Custom violinplot 8', fontsize=fs)\n\n# Custom violinplot 9\naxs[1, 3].violinplot(data, pos, points=200, vert=False, widths=1.1,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     quantiles=[[0.1], [], [], [0.175, 0.954], [0.75], [0.25]],\n                     bw_method=0.5)\naxs[1, 3].set_title('Custom violinplot 9', fontsize=fs)\n\n# Custom violinplot 10\naxs[1, 4].violinplot(data[-1:], pos[-1:], points=200, vert=False, widths=1.1,\n                     showmeans=True, showextrema=True, showmedians=True,\n                     quantiles=[0.05, 0.1, 0.8, 0.9], bw_method=0.5)\naxs[1, 4].set_title('Custom violinplot 10', fontsize=fs)"}]},{"title":"Customize plot appearance","body":["We will customize the appearance of the plot by removing y-axis labels and adding a title to the plot."],"code":[{"lang":"python","text":"for ax in axs.flat:\n    ax.set_yticklabels([])\n\nfig.suptitle(\"Violin Plotting Examples\")\nfig.subplots_adjust(hspace=0.4)\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"for ax in axs.flat:\n    ax.set_yticklabels([])\n\nfig.suptitle(\"Violin Plotting Examples\")\nfig.subplots_adjust(hspace=0.4)\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-matplotlib-hlines-and-vlines":{"intro":"In this lab, you will learn how to use hlines and vlines functions in Matplotlib. These functions are used to draw horizontal and vertical lines across a plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the libraries we need. In this lab, we will be using Matplotlib and NumPy libraries. Matplotlib is a data visualization library and NumPy is used for scientific computing with Python."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define Data","body":["The next step is to define the data that we will be using in our plot. We will use NumPy's arange function to create an array of values from 0 to 5 with a step of 0.1. We will use this array as the x-axis. We will also define the y-axis by using the exponential function and sine function from NumPy."],"code":[{"lang":"python","text":"# Define the data\nt = np.arange(0.0, 5.0, 0.1)\ns = np.exp(-t) + np.sin(2 * np.pi * t) + 1"}]},{"title":"Add Noise to Data","body":["In this step, we will add some noise to the data to make it more realistic. We will use NumPy's normal function to generate random numbers with a mean of 0.0 and a standard deviation of 0.3."],"code":[{"lang":"python","text":"# Add noise to the data\nnse = np.random.normal(0.0, 0.3, t.shape) * s"}]},{"title":"Create the Plot","body":["Now, we will create the plot using Matplotlib's subplots function. We will create two subplots, one for vertical lines and one for horizontal lines. We will set the figure size to (12, 6) for better visibility."],"code":[{"lang":"python","text":"# Create the plot\nfig, (vax, hax) = plt.subplots(1, 2, figsize=(12, 6))"}]},{"title":"Add Vertical Lines","body":["In this step, we will add vertical lines to the plot. We will use Matplotlib's vlines function to draw the vertical lines. We will also use the transform parameter to set the y-coordinates to be scaled from 0 to 1. We will draw two vertical lines at x=1 and x=2."],"code":[{"lang":"python","text":"# Add vertical lines\nvax.plot(t, s + nse, '^')\nvax.vlines(t, [0], s)\nvax.vlines([1, 2], 0, 1, transform=vax.get_xaxis_transform(), colors='r')\nvax.set_xlabel('time (s)')\nvax.set_title('Vertical lines demo')"}]},{"title":"Add Horizontal Lines","body":["In this step, we will add horizontal lines to the plot. We will use Matplotlib's hlines function to draw the horizontal lines. We will draw horizontal lines at y=0.5, y=2.5, and y=4.5."],"code":[{"lang":"python","text":"# Add horizontal lines\nhax.plot(s + nse, t, '^')\nhax.hlines(t, [0], s, lw=2)\nhax.set_xlabel('time (s)')\nhax.set_title('Horizontal lines demo')"}]},{"title":"Display the Plot","body":["Finally, we will display the plot using Matplotlib's show function."],"code":[{"lang":"python","text":"# Display the plot\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Display the plot\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-voxel-plotting-with-matplotlib":{"intro":"This lab will guide you through the process of creating a 3D voxel plot using the Matplotlib library in Python. Voxel plots are useful for visualizing 3D data in a way that is both clear and aesthetically pleasing. In this lab, we will be using the Axes3D.voxels function to create a voxel plot of two cubes and a link between them.","steps":[{"title":"Import necessary libraries","body":["First, we need to import the necessary libraries. In this case, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Prepare coordinates","body":["Next, we will prepare the coordinates for our voxel plot. We will be creating an 8x8x8 grid of points using NumPy's indices function."],"code":[{"lang":"python","text":"x, y, z = np.indices((8, 8, 8))"}]},{"title":"Create the cubes and link","body":["Now, we will create the two cubes and the link between them. We will do this by defining three boolean arrays that will be combined into a single boolean array. The first two arrays define the location of the cubes, while the third array defines the location of the link."],"code":[{"lang":"python","text":"cube1 = (x < 3) & (y < 3) & (z < 3)\ncube2 = (x >= 5) & (y >= 5) & (z >= 5)\nlink = abs(x - y) + abs(y - z) + abs(z - x) <= 2\n\nvoxelarray = cube1 | cube2 | link"}]},{"title":"Set colors","body":["We will now set the colors for each object in the voxel plot. We will do this by creating an empty array of the same shape as the boolean array we created in Step 3, and then setting the color of each object based on its location."],"code":[{"lang":"python","text":"colors = np.empty(voxelarray.shape, dtype=object)\ncolors[link] = 'red'\ncolors[cube1] = 'blue'\ncolors[cube2] = 'green'"}]},{"title":"Plot the voxel array","body":["Finally, we can use the Axes3D.voxels function to plot the voxel array with the specified colors."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(voxelarray, facecolors=colors, edgecolor='k')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(voxelarray, facecolors=colors, edgecolor='k')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-3d-voxel-plot-of-the-numpy-logo":{"intro":"This lab demonstrates how to use the Axes3D.voxels function in Matplotlib to create a 3D voxel plot of the NumPy logo.","steps":[{"title":"Import libraries","body":["First, we need to import the necessary libraries, which are Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Define the explode function","body":["Next, we define a function called explode that will be used to upscale the voxel image of the NumPy logo. This function takes in a NumPy array as its input and returns a new NumPy array that is twice the size of the input array."],"code":[{"lang":"python","text":"def explode(data):\n    size = np.array(data.shape)*2\n    data_e = np.zeros(size - 1, dtype=data.dtype)\n    data_e[::2, ::2, ::2] = data\n    return data_e"}]},{"title":"Build the NumPy logo","body":["Now we can begin to build the NumPy logo using a 3D NumPy array called n_voxels. We set certain elements in the array to True to represent the logo's shape. We also define two other NumPy arrays called facecolors and edgecolors that will be used to color the voxels."],"code":[{"lang":"python","text":"n_voxels = np.zeros((4, 3, 4), dtype=bool)\nn_voxels[0, 0, :] = True\nn_voxels[-1, 0, :] = True\nn_voxels[1, 0, 2] = True\nn_voxels[2, 0, 1] = True\n\nfacecolors = np.where(n_voxels, '#FFD65DC0', '#7A88CCC0')\nedgecolors = np.where(n_voxels, '#BFAB6E', '#7D84A6')"}]},{"title":"Upscale the voxel image","body":["We now use the explode function defined earlier to upscale the voxel image, leaving gaps between each voxel."],"code":[{"lang":"python","text":"filled = np.ones(n_voxels.shape)\nfilled_2 = explode(filled)\nfcolors_2 = explode(facecolors)\necolors_2 = explode(edgecolors)"}]},{"title":"Shrink the gaps","body":["We shrink the gaps between each voxel by modifying the coordinates of each voxel using NumPy's indices function."],"code":[{"lang":"python","text":"x, y, z = np.indices(np.array(filled_2.shape) + 1).astype(float) // 2\nx[0::2, :, :] += 0.05\ny[:, 0::2, :] += 0.05\nz[:, :, 0::2] += 0.05\nx[1::2, :, :] += 0.95\ny[:, 1::2, :] += 0.95\nz[:, :, 1::2] += 0.95"}]},{"title":"Create the voxel plot","body":["Finally, we create the 3D voxel plot using the voxels function of the Axes3D class in Matplotlib."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(x, y, z, filled_2, facecolors=fcolors_2, edgecolors=ecolors_2)\nax.set_aspect('equal')\n\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(x, y, z, filled_2, facecolors=fcolors_2, edgecolors=ecolors_2)\nax.set_aspect('equal')\n\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-create-3d-voxel-plots-with-rgb":{"intro":"In this lab, you will learn how to create a 3D voxel plot with RGB colors using Matplotlib. Voxel plots are a way of representing 3D data on a 2D plot by using cubes to represent the data points. The RGB colors will be used to represent the different values of the data.","steps":[{"title":"Importing Libraries","body":["Before creating the plot, we need to import the required libraries. In this case, we will be using Matplotlib and NumPy."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np"}]},{"title":"Defining the Coordinates and Colors","body":["Defining the Coordinates and Colors","Next, we need to define the coordinates and colors for the plot. In this example, we will use the np.indices function to create a 17x17x17 grid of values for the RGB colors.","We will also define a function midpoints to find the midpoints between the values in the grid. This will be used later to create the sphere."],"code":[{"lang":"python","text":"r, g, b = np.indices((17, 17, 17)) / 16.0"},{"lang":"python","text":"def midpoints(x):\n    sl = ()\n    for _ in range(x.ndim):\n        x = (x[sl + np.index_exp[:-1]] + x[sl + np.index_exp[1:]]) / 2.0\n        sl += np.index_exp[:]\n    return x"}]},{"title":"Creating the Sphere","body":["We will now create a sphere in the plot by defining a condition for the RGB values that lie within a certain distance from the center of the plot."],"code":[{"lang":"python","text":"rc = midpoints(r)\ngc = midpoints(g)\nbc = midpoints(b)\n\nsphere = (rc - 0.5)**2 + (gc - 0.5)**2 + (bc - 0.5)**2 < 0.5**2"}]},{"title":"Combining the Colors","body":["We will now combine the RGB color components into a single array of shape (17, 17, 17, 3)."],"code":[{"lang":"python","text":"colors = np.zeros(sphere.shape + (3,))\ncolors[..., 0] = rc\ncolors[..., 1] = gc\ncolors[..., 2] = bc"}]},{"title":"Plotting the Voxel Plot","body":["Finally, we can plot the voxel plot using the ax.voxels function. We will pass in the RGB values, the condition for the sphere, the face colors, edge colors, and linewidth."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(r, g, b, sphere,\n          facecolors=colors,\n          edgecolors=np.clip(2*colors - 0.5, 0, 1),  # brighter\n          linewidth=0.5)\nax.set(xlabel='r', ylabel='g', zlabel='b')\nax.set_aspect('equal')\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(r, g, b, sphere,\n          facecolors=colors,\n          edgecolors=np.clip(2*colors - 0.5, 0, 1),  # brighter\n          linewidth=0.5)\nax.set(xlabel='r', ylabel='g', zlabel='b')\nax.set_aspect('equal')\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-creating-3d-voxel-plots-in-matplotlib":{"intro":"In this lab, you will learn how to create a 3D voxel plot using cylindrical coordinates in Matplotlib. The plot will demonstrate how to use the _x_, _y_, and _z_ parameters of .Axes3D.voxels to create a 3D voxel plot.","steps":[{"title":"Import Libraries","body":["The first step is to import the necessary libraries for this lab. We will be using matplotlib.pyplot, numpy, and matplotlib.colors."],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.colors"}]},{"title":"Define Midpoints Function","body":["Next, we define a midpoints function to calculate the midpoints of an array of coordinates. This function will be used later to calculate the midpoints of r, theta, and z."],"code":[{"lang":"python","text":"def midpoints(x):\n    sl = ()\n    for i in range(x.ndim):\n        x = (x[sl + np.index_exp[:-1]] + x[sl + np.index_exp[1:]]) / 2.0\n        sl += np.index_exp[:]\n    return x"}]},{"title":"Define Coordinates and RGB Values","body":["Define Coordinates and RGB Values","In this step, we define the coordinates r, theta, and z, and attach RGB values to each."],"code":[{"lang":"python","text":"r, theta, z = np.mgrid[0:1:11j, 0:np.pi*2:25j, -0.5:0.5:11j]\nx = r*np.cos(theta)\ny = r*np.sin(theta)\n\nrc, thetac, zc = midpoints(r), midpoints(theta), midpoints(z)\n\n# define a wobbly torus about [0.7, *, 0]\nsphere = (rc - 0.7)**2 + (zc + 0.2*np.cos(thetac*2))**2 < 0.2**2\n\n# combine the color components\nhsv = np.zeros(sphere.shape + (3,))\nhsv[..., 0] = thetac / (np.pi*2)\nhsv[..., 1] = rc\nhsv[..., 2] = zc + 0.5\ncolors = matplotlib.colors.hsv_to_rgb(hsv)"}]},{"title":"Create the 3D Voxel Plot","body":["Now we create the 3D voxel plot using the ax.voxels function. We pass in x, y, z, and sphere as the parameters. We also add facecolors and edgecolors using the colors array we defined earlier."],"code":[{"lang":"python","text":"ax = plt.figure().add_subplot(projection='3d')\nax.voxels(x, y, z, sphere,\n          facecolors=colors,\n          edgecolors=np.clip(2*colors - 0.5, 0, 1),  # brighter\n          linewidth=0.5)"}]},{"title":"Display the Plot","body":["Finally, we display the plot using the plt.show() function."],"code":[{"lang":"python","text":"plt.show()"}]}],"commands":[],"reference":[],"source":"matplotlib/matplotlib · BSD 3-Clause"},"labex-matplotlib-overlay-image-on-matplotlib-plot":{"intro":"This tutorial will show you how to overlay an image on a Matplotlib plot by moving it to the front and making it semi-transparent. The tutorial uses the figimage method from the matplotlib.figure.Figure class and the imread method from the matplotlib.image module.","steps":[{"title":"Creating a Jupyter Notebook and Importing Required Libraries","body":["In the first cell of your notebook, enter the following code to import the necessary libraries:","Let's understand what each of these libraries does:","• matplotlib.pyplot (aliased as plt): A collection of functions that make matplotlib work like MATLAB, providing a convenient interface for creating plots. • numpy (aliased as np): A fundamental package for scientific computing in Python, which we'll use for data manipulation. • matplotlib.cbook: A collection of utility functions for matplotlib, including functions to get sample data. • matplotlib.image: A module for image-related functionality in matplotlib, which we'll use to read and display images.","![libraries-imported](../assets/screenshot-20250306-18gJ6FRZ@2x.png)"],"code":[{"lang":"python","text":"import matplotlib.pyplot as plt\nimport numpy as np\nimport matplotlib.cbook as cbook\nimport matplotlib.image as image"}]},{"title":"Loading and Examining the Image","body":["Loading and Examining the Image","Now that we have imported our libraries, we need to load the image that we want to overlay on our plot. Matplotlib provides some sample images that we can use for practice.","• Create a new cell in your notebook and enter the following code:","• Uses cbook.get_sample_data() to load a sample image named 'logo2.png' from Matplotlib's sample data collection. • Uses image.imread() to read the image file into a NumPy array. • Prints information about the image dimensions and data type. • Creates a figure and displays the image using plt.imshow(). • Hides the axis ticks and labels with plt.axis('off'). • Adds a title to the figure. • Displays the figure using plt.show()."],"code":[{"lang":"python","text":"# Load the sample image\nwith cbook.get_sample_data('logo2.png') as file:\n    im = image.imread(file)\n\n# Display information about the image\nprint(f\"Image shape: {im.shape}\")\nprint(f\"Image data type: {im.dtype}\")\n\n# Display the image\nplt.figure(figsize=(4, 4))\nplt.imshow(im)\nplt.axis('off')  # Hide axis\nplt.title('Matplotlib Logo')\nplt.show()"}]},{"title":"Creating a Basic Plot with Random Data","body":["Creating a Basic Plot with Random Data","Before we add our image overlay, we need to create a plot that will serve as the base for our visualization. Let's create a simple bar chart using random data.","• Create a new cell in your notebook and enter the following code:","• Creates a figure and axes with a specific size using plt.subplots(). • Sets a random seed to ensure we get the same random values each time we run the code. • Generates 30 x-values (0 through 29) and corresponding y-values (x plus random noise). • Creates a bar chart with green bars using ax.bar(). • Adds grid lines to the plot with ax.grid(). • Adds labels for the x-axis, y-axis, and a title for the plot. • Uses plt.tight_layout() to adjust spacing for better appearance. • Displays the plot using plt.show()."],"code":[{"lang":"python","text":"# Create a figure and axes for our plot\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data\nx = np.arange(30)  # x-axis values (0 to 29)\ny = x + np.random.randn(30)  # y-axis values (x plus random noise)\n\n# Create a bar chart\nbars = ax.bar(x, y, color='#6bbc6b')  # Green bars\n\n# Add grid lines\nax.grid(linestyle='--', alpha=0.7)\n\n# Add labels and title\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')\nax.set_title('Bar Chart with Random Data')\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}]},{"title":"Overlaying the Image on the Plot","body":["Overlaying the Image on the Plot","Now that we have created our base plot, let's overlay the image on it. We'll use the figimage method to add the image to the figure, and we'll make it semi-transparent so that the plot underneath remains visible.","• Create a new cell in your notebook and enter the following code:","This code combines what we did in the previous steps and adds the figimage method to overlay our image on the plot. Here's a breakdown of the figimage parameters:"],"code":[{"lang":"python","text":"# Create a figure and axes for our plot (same as before)\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data\nx = np.arange(30)  # x-axis values (0 to 29)\ny = x + np.random.randn(30)  # y-axis values (x plus random noise)\n\n# Create a bar chart\nbars = ax.bar(x, y, color='#6bbc6b')  # Green bars\n\n# Add grid lines\nax.grid(linestyle='--', alpha=0.7)\n\n# Add labels and title\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')\nax.set_title('Bar Chart with Image Overlay')\n\n# Load the image\nwith cbook.get_sample_data('logo2.png') as file:\n    im = image.imread(file)\n\n# Overlay the image on the plot\n# Parameters:\n# - im: the image data\n# - 25, 25: x and y position in pixels from the bottom left\n# - zorder=3: controls the drawing order (higher numbers are drawn on top)\n# - alpha=0.5: controls the transparency (0 = transparent, 1 = opaque)\nfig.figimage(im, 25, 25, zorder=3, alpha=0.5)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"},{"lang":"python","text":"# Create a figure and axes for our plot\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data\nx = np.arange(30)\ny = x + np.random.randn(30)\n\n# Create a bar chart\nbars = ax.bar(x, y, color='#6bbc6b')\nax.grid(linestyle='--', alpha=0.7)\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')\nax.set_title('Bar Chart with Centered Image Overlay')\n\n# Load the image\nwith cbook.get_sample_data('logo2.png') as file:\n    im = image.imread(file)\n\n# Get figure dimensions\nfig_width, fig_height = fig.get_size_inches() * fig.dpi\n\n# Calculate center position (this is approximate)\nx_center = fig_width / 2 - im.shape[1] / 2\ny_center = fig_height / 2 - im.shape[0] / 2\n\n# Overlay the image at the center with higher transparency\nfig.figimage(im, x_center, y_center, zorder=3, alpha=0.3)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}]},{"title":"Creating a Reusable Function for Image Overlays","body":["Creating a Reusable Function for Image Overlays","To make our code more reusable, let's create a function that can add an image overlay to any Matplotlib figure. This way, we can easily apply the same effect to different plots.","• Create a new cell in your notebook and enter the following code:","This code defines a function called add_image_overlay that:"],"code":[{"lang":"python","text":"def add_image_overlay(fig, image_path, x_pos=25, y_pos=25, alpha=0.5, zorder=3):\n    \"\"\"\n    Add an image overlay to a matplotlib figure.\n\n    Parameters:\n    -----------\n    fig : matplotlib.figure.Figure\n        The figure to add the image to\n    image_path : str\n        Path to the image file\n    x_pos : int\n        X position in pixels from the bottom left\n    y_pos : int\n        Y position in pixels from the bottom left\n    alpha : float\n        Transparency level (0 to 1)\n    zorder : int\n        Drawing order (higher numbers are drawn on top)\n\n    Returns:\n    --------\n    fig : matplotlib.figure.Figure\n        The figure with the image overlay\n    \"\"\"\n    # Load the image\n    with cbook.get_sample_data(image_path) as file:\n        im = image.imread(file)\n\n    # Add the image to the figure\n    fig.figimage(im, x_pos, y_pos, zorder=zorder, alpha=alpha)\n\n    return fig\n\n# Example usage: Create a scatter plot with an image overlay\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Set a random seed for reproducibility\nnp.random.seed(19680801)\n\n# Generate random data for a scatter plot\nx = np.random.rand(50) * 10\ny = np.random.rand(50) * 10\n\n# Create a scatter plot\nax.scatter(x, y, s=100, c=np.random.rand(50), cmap='viridis', alpha=0.7)\nax.grid(linestyle='--', alpha=0.7)\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')"},{"lang":"python","text":"# Example usage: Create a line plot with an image overlay\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate data for a line plot\nx = np.linspace(0, 10, 100)\ny = np.sin(x)\n\n# Create a line plot\nax.plot(x, y, linewidth=2, color='#d62728')\nax.grid(linestyle='--', alpha=0.7)\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')\nax.set_title('Sine Wave with Image Overlay')\nax.set_ylim(-1.5, 1.5)\n\n# Add the image overlay using our function\n# Place it in the bottom right corner\nfig_width, fig_height = fig.get_size_inches() * fig.dpi\nwith cbook.get_sample_data('logo2.png') as file:\n    im = image.imread(file)\n    x_pos = fig_width - im.shape[1] - 50  # 50 pixels from the right edge\n\nadd_image_overlay(fig, 'logo2.png', x_pos=x_pos, y_pos=50, alpha=0.6)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}]}],"commands":[],"reference":[{"path":"reference.py","text":"# Example usage: Create a line plot with an image overlay\nfig, ax = plt.subplots(figsize=(10, 6))\n\n# Generate data for a line plot\nx = np.linspace(0, 10, 100)\ny = np.sin(x)\n\n# Create a line plot\nax.plot(x, y, linewidth=2, color='#d62728')\nax.grid(linestyle='--', alpha=0.7)\nax.set_xlabel('X-axis Label')\nax.set_ylabel('Y-axis Label')\nax.set_title('Sine Wave with Image Overlay')\nax.set_ylim(-1.5, 1.5)\n\n# Add the image overlay using our function\n# Place it in the bottom right corner\nfig_width, fig_height = fig.get_size_inches() * fig.dpi\nwith cbook.get_sample_data('logo2.png') as file:\n    im = image.imread(file)\n    x_pos = fig_width - im.shape[1] - 50  # 50 pixels from the right edge\n\nadd_image_overlay(fig, 'logo2.png', x_pos=x_pos, y_pos=50, alpha=0.6)\n\n# Display the plot\nplt.tight_layout()\nplt.show()"}],"source":"matplotlib/matplotlib · BSD 3-Clause"}};
